INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'germany','Germany','de',1,'Engineering Powerhouse & World-Class Public Education','Study at public and private universities and explore Bachelor’s, Master’s and vocational Ausbildung pathways.','Germany is a premier destination for international students looking for strong academic programs, zero or minimal tuition fees at public universities, diverse career-oriented pathways, and the 18-month post-study job seeker visa.','€0 - €3,000 / semester (Public Universities)','€11,208 / year (Blocked Account requirement)','140 full days or 280 half days / year; 18 months Job Seeker Visa','[\"Engineering & Mechatronics\", \"Computer Science & IT\", \"Data Science & Artificial Intelligence\", \"Business & Management\", \"Mechanical & Automotive Engineering\", \"Electrical Engineering\", \"Healthcare & Nursing\", \"Vocational Education & Ausbildung\"]','[\"Tuition-free or low-cost higher education at world-ranked public universities\", \"Specialized dMAT assessment guidance for Master’s admissions\", \"18-month residence permit post-graduation to find professional employment\", \"Ausbildung (dual vocational training) pathways with paid stipends\", \"Direct pathway to the EU Blue Card and permanent residency\"]','[{\"city\": \"Munich\", \"name\": \"Technical University of Munich (TUM)\", \"rank\": \"#37 QS World\"}, {\"city\": \"Aachen\", \"name\": \"RWTH Aachen University\", \"rank\": \"#106 QS World\"}, {\"city\": \"Karlsruhe\", \"name\": \"Karlsruhe Institute of Technology (KIT)\", \"rank\": \"#119 QS World\"}, {\"city\": \"Berlin\", \"name\": \"TU Berlin\", \"rank\": \"#154 QS World\"}, {\"city\": \"Stuttgart\", \"name\": \"University of Stuttgart\", \"rank\": \"#312 QS World\"}, {\"city\": \"Berlin / Bad Honnef\", \"name\": \"IU International University of Applied Sciences\", \"rank\": \"Top Applied Science\"}]',1,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (2,'austria','Austria','at',0,'High Living Standard in the Heart of Central Europe','Explore higher education opportunities and pathways for international students.','Austria offers an exceptional quality of life, Vienna consistently ranking as the world’s most livable city. Public universities offer minimal tuition fees and rigorous research standards in tech and business.','€726 - €1,500 / semester (Public Universities)','€9,000 - €12,000 / year','20 hrs/week; 12-month post-study Red-White-Red Card job seeker visa','[\"Business & Economics\", \"Management\", \"Technology & Engineering\", \"Computer Science\", \"Applied Sciences\"]','[\"Vienna ranked repeatedly as the #1 most livable city in the world\", \"Very affordable semester fees for international students\", \"12-month Red-White-Red Card job seeker visa for graduates\", \"Strong research ties with Germany and Central European industries\"]','[{\"city\": \"Vienna\", \"name\": \"University of Vienna\", \"rank\": \"#130 QS World\"}, {\"city\": \"Vienna\", \"name\": \"Vienna University of Technology (TU Wien)\", \"rank\": \"#179 QS World\"}, {\"city\": \"Graz\", \"name\": \"Graz University of Technology (TU Graz)\", \"rank\": \"#269 QS World\"}]',2,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (3,'italy','Italy','it',0,'Heritage of Innovation, Architecture, Design & Tech','Choose from a wide range of academic programs and universities.','Italy boasts the oldest universities in the Western world alongside cutting-edge polytechnics known for automotive design, civil engineering, robotics, and economics, with generous regional DSU scholarships.','€1,000 - €4,000 / year (Public Universities)','€6,000 - €9,000 / year (DSU scholarships can cover full living & fees)','20 hrs/week; 1-year stay-back permit for Masters/PhD graduates','[\"Engineering & Automotive\", \"Architecture & Urban Planning\", \"Business & Economics\", \"Management\", \"Computer Science\", \"Industrial Design & Fashion\"]','[\"DSU and regional income-based scholarships covering tuition + stipend\", \"World-famous polytechnics (Politecnico di Milano & Politecnico di Torino)\", \"Rich industrial linkages with Ferrari, Lamborghini, Eni, and Luxottica\", \"Low tuition fee structures for international students\"]','[{\"city\": \"Milan\", \"name\": \"Politecnico di Milano\", \"rank\": \"#111 QS World\"}, {\"city\": \"Rome\", \"name\": \"Sapienza University of Rome\", \"rank\": \"#134 QS World\"}, {\"city\": \"Bologna\", \"name\": \"University of Bologna\", \"rank\": \"#133 QS World\"}, {\"city\": \"Turin\", \"name\": \"Politecnico di Torino\", \"rank\": \"#241 QS World\"}]',3,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (4,'finland','Finland','fi',0,'World #1 in Education Quality, Clean Tech & AI Innovation','Discover high-tech research universities, generous scholarships, and Nordic innovation.','Finland is globally celebrated for world-leading education quality, cutting-edge technology universities, high safety, and a 2-year post-study residence permit for international graduates.','€8,000 - €15,000 / year (Scholarships up to 50-100%)','€700 - €900 / month (~€8,400 - €10,800 / year)','30 hrs/week during term; 2-year post-study work search visa','[\"Computer Science & AI\", \"Information Technology\", \"Clean & Renewable Energy\", \"Business & Management\", \"Biomedical Engineering\", \"Data Science & Analytics\"]','[\"Ranked the Happiest Country in the World for 7 consecutive years\", \"Generous university scholarship waivers covering 20% to 100% of tuition\", \"2-year post-study residence permit for graduates to seek employment\", \"Dynamic tech startup and gaming ecosystem (Nokia, Supercell, Slush)\"]','[{\"city\": \"Espoo\", \"name\": \"Aalto University\", \"rank\": \"#109 QS World\"}, {\"city\": \"Helsinki\", \"name\": \"University of Helsinki\", \"rank\": \"#115 QS World\"}, {\"city\": \"Lappeenranta\", \"name\": \"LUT University\", \"rank\": \"#351 QS World\"}, {\"city\": \"Tampere\", \"name\": \"Tampere University\", \"rank\": \"#436 QS World\"}]',4,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (5,'spain','Spain','es',0,'Dynamic International Campuses & Global Business Excellence','Discover Bachelor’s and Master’s opportunities in an international environment.','Spain combines top-ranked European business schools, affordable tuition fees, and rich cultural heritage. Spanish universities offer an increasing number of fully English-taught programs in tech and business.','€2,500 - €16,000 / year','€7,000 - €10,000 / year','Up to 30 hrs/week with work authorization; 1-year job seeker visa','[\"Business Administration\", \"International Management\", \"Engineering\", \"Technology & CS\", \"Hospitality & Tourism\", \"Digital Marketing\"]','[\"Affordable living costs relative to Western Europe\", \"Home to top 10 global business schools (IE, ESADE, IESE)\", \"Opportunity to learn Spanish, the world’s second most spoken native language\", \"Vibrant startup ecosystems in Barcelona and Madrid\"]','[{\"city\": \"Madrid / Segovia\", \"name\": \"IE University\", \"rank\": \"Top Global Business\"}, {\"city\": \"Barcelona\", \"name\": \"University of Barcelona\", \"rank\": \"#164 QS World\"}, {\"city\": \"Madrid\", \"name\": \"Autonomous University of Madrid\", \"rank\": \"#199 QS World\"}, {\"city\": \"Barcelona\", \"name\": \"ESADE Business School\", \"rank\": \"Top 20 Worldwide\"}]',5,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (6,'netherlands','Netherlands','nl',0,'High-Tech Innovation & Continental European Business Hub','Discover internationally recognised programs across technology, business, engineering and other fields.','The Netherlands offers the largest range of English-taught programs in mainland Europe. Known for interactive problem-based learning and strong connections to tech and logistics multinational hubs.','€8,000 - €18,000 / year','€10,000 - €14,000 / year','16 hrs/week during study; 1-year Orientation Year (Zoekjaar) visa','[\"Computer Science\", \"Data Science\", \"Business Administration\", \"Engineering\", \"Artificial Intelligence\", \"Information Sciences\", \"Management\"]','[\"Over 2,100 programs taught entirely in English\", \"1-year Zoekjaar (orientation year) work visa for graduates\", \"World-leading research universities in science, tech, and agriculture\", \"Progressive, safe, and multilingual environment\"]','[{\"city\": \"Delft\", \"name\": \"Delft University of Technology (TU Delft)\", \"rank\": \"#47 QS World\"}, {\"city\": \"Amsterdam\", \"name\": \"University of Amsterdam\", \"rank\": \"#53 QS World\"}, {\"city\": \"Eindhoven\", \"name\": \"Eindhoven University of Technology (TU/e)\", \"rank\": \"#124 QS World\"}, {\"city\": \"Rotterdam\", \"name\": \"Erasmus University Rotterdam\", \"rank\": \"Top Business\"}]',6,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (7,'poland','Poland','pl',0,'High-Quality & Highly Affordable European Education','Explore affordable European education opportunities across multiple disciplines.','Poland has emerged as a favorite study destination for budget-conscious international students, offering affordable tuition, reasonable living expenses, and world-class medical, nursing, and IT faculties.','€2,000 - €4,500 / year','€4,500 - €6,500 / year','Full-time during holidays, 20 hrs/week; 9-month stay-back for work search','[\"Nursing & Healthcare\", \"Engineering & Mechatronics\", \"Computer Science\", \"Business & Logistics\", \"Management\", \"Applied Technology\"]','[\"One of the most cost-effective study destinations in the European Union\", \"Direct admission pathways for Nursing & Healthcare degrees\", \"Rapidly growing tech and IT outsourcing hub in Central Europe\", \"Schengen mobility throughout 29 European countries\"]','[{\"city\": \"Warsaw\", \"name\": \"University of Warsaw\", \"rank\": \"#262 QS World\"}, {\"city\": \"Krakow\", \"name\": \"Jagiellonian University\", \"rank\": \"#304 QS World\"}, {\"city\": \"Warsaw\", \"name\": \"Warsaw University of Technology\", \"rank\": \"Top Tech\"}, {\"city\": \"Wroclaw\", \"name\": \"Wroclaw University of Science & Technology\", \"rank\": \"Top Engineering\"}]',7,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (8,'latvia','Latvia','lv',0,'Where Baltic Innovation Meets Academic Value','Earn an internationally recognised European degree in Riga and beyond.','Latvia offers international students affordable European degrees, prestigious medicine and engineering universities in Riga, and accessible living costs in the euro area.','€2,500 - €6,000 / year (Medicine: €10,000 - €15,000)','€450 - €700 / month (~€5,400 - €8,400 / year)','20 hrs/week during term / full-time in holidays; post-study job search options','[\"Medicine & Dentistry\", \"Engineering & Technology\", \"Information Technology & Data Science\", \"Business & Finance\", \"Aviation & Transport Logistics\"]','[\"Accessible tuition and living costs in the euro area\", \"Renowned English-medium medical faculties (RSU) and engineering (RTU)\", \"60+ nationalities represented in an international student environment\", \"Member of EU and Schengen zone with modern digital infrastructure\"]','[{\"city\": \"Riga\", \"name\": \"Riga Technical University (RTU)\", \"rank\": \"#741-750 QS World\"}, {\"city\": \"Riga\", \"name\": \"University of Latvia\", \"rank\": \"#801-850 QS World\"}, {\"city\": \"Riga\", \"name\": \"Rīga Stradiņš University (RSU)\", \"rank\": \"Top Medical\"}, {\"city\": \"Riga\", \"name\": \"BA School of Business and Finance\", \"rank\": \"Top Business\"}]',8,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `destinations` (`id`, `slug`, `name`, `code`, `is_primary`, `headline`, `tagline`, `overview`, `tuition_range`, `living_cost`, `work_rights`, `popular_study_areas`, `highlights`, `top_universities`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (9,'lithuania','Lithuania','lt',0,'Where Baltic Excellence Meets Digital Ambition','Earn a respected European degree in Vilnius, Kaunas and beyond with exceptional value.','Lithuania offers international students recognized European qualifications, 500+ English-taught programmes, cutting-edge fintech and IT hubs, and remarkably accessible living costs.','€1,500 - €6,000 / year (Medicine: €10,000 - €14,000)','€500 - €800 / month (~€6,000 - €9,600 / year)','Up to 40 hrs/week for students with residence permit; 1-year post-study job seeker permit','[\"Medicine & Dentistry\", \"Information Technology & Data Science\", \"Engineering & Mechatronics\", \"Business & FinTech\", \"Pharmacy & Health Sciences\"]','[\"Over 500 English-taught programs across universities & applied sciences\", \"Students with residence permit can work up to 40 hours per week\", \"1-year post-study residence permit for eligible graduates\", \"Leading European fintech, laser technology, and life sciences hub\"]','[{\"city\": \"Vilnius\", \"name\": \"Vilnius University\", \"rank\": \"#439 QS World\"}, {\"city\": \"Kaunas\", \"name\": \"Kaunas University of Technology (KTU)\", \"rank\": \"#751-760 QS\"}, {\"city\": \"Vilnius\", \"name\": \"Vilnius Gediminas Technical University (VILNIUS TECH)\", \"rank\": \"#801-850 QS\"}, {\"city\": \"Kaunas\", \"name\": \"Lithuanian University of Health Sciences (LSMU)\", \"rank\": \"Top Health\"}]',9,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
