/*!40000 ALTER TABLE `pages` DISABLE KEYS */;
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (1,'germany/bachelor','pathway',1,'Bachelor\'s in Germany','Bachelor','An undergraduate education of international standing at world-renowned German public universities, with zero tuition in 15 of 16 federal states.','[{\"lead\": \"An undergraduate education of international standing at world-renowned public universities (<em>staatliche Hochschulen</em>) — with zero tuition in 15 of 16 federal states.\", \"type\": \"hero\", \"title\": \"Bachelor’s Degrees at German Public Universities\", \"eyebrow\": \"Germany · Undergraduate admissions\"}, {\"id\": \"overview\", \"type\": \"intro\", \"title\": \"An Introduction to Undergraduate Study\", \"eyebrow\": \"Overview & scope\", \"paragraphs\": [\"Germany’s public universities (<em>staatliche Hochschulen</em>) are among the oldest and most respected institutions in Europe. They are funded principally by the federal states and are known for rigorous scholarship, close links between research and teaching, and a tradition of broad access. For international applicants, they offer an undergraduate education of international standing at a cost far below that of comparable institutions in the English-speaking world.\", \"A Bachelor’s degree at a public university typically takes <strong>six to eight semesters (3 to 4 years)</strong>, depending on the discipline and institution. Successful candidates receive the <strong>Bachelorzeugnis</strong>, the official certificate recording the field of study and the final grade. Degrees are awarded in engineering, the natural sciences, the humanities, the social sciences, economics and management, and the arts. Most programmes are taught in German, while a growing number are taught wholly or partly in English.\"]}, {\"id\": \"why-public\", \"type\": \"cards\", \"items\": [{\"desc\": \"German public universities have produced generations of eminent scholars, scientists and engineers, and their qualifications are recognised across Europe and beyond.\", \"title\": \"Academic reputation\"}, {\"desc\": \"Most public universities charge no tuition fees to international undergraduates. Students pay a modest semester contribution (Semesterbeitrag), which usually covers administrative costs and often a regional transport pass. The state of Baden-Württemberg levies tuition on students from outside the EU, so applicants should confirm the position at their chosen institution and state.\", \"title\": \"Affordability\"}, {\"desc\": \"Many degrees incorporate internships, laboratory work and industry placements, and students may take part-time employment within the limits of their visa conditions.\", \"title\": \"Practical orientation\"}, {\"desc\": \"The German system places considerable trust in the student. This fosters self-discipline, critical thinking, and intellectual maturity.\", \"title\": \"Independence of study\"}], \"style\": \"plain\", \"title\": \"Why Choose a Public University\", \"columns\": 4, \"eyebrow\": \"The public advantage\"}, {\"id\": \"requirements\", \"type\": \"intro\", \"title\": \"Admission Requirements\", \"eyebrow\": \"Eligibility criteria\", \"paragraphs\": [\"Admission to a public university depends on three principal considerations: <strong>educational qualification</strong>, <strong>language proficiency</strong>, and <strong>documentation</strong>.\"]}, {\"type\": \"cards\", \"intro\": \"German universities generally expect thirteen years of schooling before entry to a Bachelor’s programme. Applicants from India, who typically complete twelve years, must therefore bridge the shortfall by one of the following routes:\", \"items\": [{\"desc\": \"A preparatory foundation course, normally lasting two semesters, that concludes with the Feststellungsprüfung (FSP). Entry is by an Aufnahmeprüfung (entrance examination).\", \"title\": \"Studienkolleg\"}, {\"desc\": \"Applicants who completed a year of a relevant undergraduate programme at a recognised Indian university may apply directly in many cases.\", \"title\": \"1 Year University Study in India\"}, {\"desc\": \"Certain qualifications, such as the International Baccalaureate (IB) and a strong result in JEE Advanced (for relevant subjects), may be accepted for direct entry.\", \"title\": \"Recognised Exemptions\"}], \"style\": \"plain\", \"title\": \"1. Educational Qualification and the Thirteen-Year Requirement\", \"columns\": 3}, {\"note\": \"*Each university makes the final eligibility decision based on Anabin database evaluation.\", \"type\": \"steps\", \"items\": [{\"tag\": \"Input Basis\", \"desc\": \"\", \"title\": \"12 Years of Schooling\"}, {\"tag\": \"Check 1 or Check 2\", \"desc\": \"\", \"title\": \"Exemption / 1 Yr Degree?\"}, {\"tag\": \"Outcome\", \"desc\": \"\", \"title\": \"Direct Entry OR Studienkolleg + FSP\"}], \"title\": \"Two checks decide whether the Studienkolleg is required:\"}, {\"type\": \"cards\", \"items\": [{\"desc\": \"Generally require CEFR level C1 proficiency, evidenced by TestDaF, DSH, or Goethe-Zertifikat C1.\", \"title\": \"German-Taught Programmes\"}, {\"desc\": \"Require IELTS or TOEFL (IELTS 6.5+ benchmark). German proficiency is not required for admission, but strongly advised for daily life.\", \"title\": \"English-Taught Programmes\"}], \"style\": \"plain\", \"title\": \"2. Language Proficiency\", \"columns\": 2}, {\"type\": \"checklist\", \"intro\": \"Applicants should normally be prepared to submit:\", \"items\": [\"Class 10 and Class 12 mark sheets\", \"Official school-leaving certificate\", \"Evidence of German or English language proficiency\", \"Curriculum vitae and motivation letter\", \"Uni-assist documentation & APS certificate\"], \"title\": \"3. Documentation\", \"columns\": 2}, {\"id\": \"pathway\", \"type\": \"split\", \"intro\": \"Choose your admission track based on your prior schooling and language medium.\", \"title\": \"The Application Pathway\", \"columns\": [{\"badge\": \"Route A\", \"title\": \"Via Studienkolleg (German-taught programmes)\", \"points\": [\"Shortlist universities\", \"Check eligibility\", \"Language preparation\", \"Document preparation\", \"Submit application\", \"Receive entrance exam invitation\", \"Open blocked account\", \"Apply for student visa\", \"Travel and health insurance\", \"Pass the entrance exam\", \"Studienkolleg and FSP\", \"Apply to the Bachelor’s course\"], \"paragraphs\": [\"Applicants who need the foundation year follow twelve stages, with the Aufnahmeprüfung and the Feststellungsprüfung (FSP) as key milestones.\"]}, {\"badge\": \"Route B\", \"title\": \"Direct Entry (Principally English-taught programmes)\", \"points\": [\"Shortlist course and university\", \"Check eligibility\", \"Language certification\", \"Document preparation\", \"Submit application\", \"Receive offer of admission\", \"Open blocked account\", \"Apply for student visa\", \"Travel and health insurance\", \"Enrol and begin studies\"], \"paragraphs\": [\"Applicants who qualify for an exemption, or who hold a relevant year of university study, proceed in ten stages without a foundation year.\"]}], \"eyebrow\": \"Step-by-step workflows\", \"ordered\": true}, {\"id\": \"costs\", \"type\": \"stats\", \"intro\": \"Public universities charge little or nothing in tuition, but students must still demonstrate that they can meet their living expenses. Visa applicants are required to fund a blocked account (Sperrkonto), currently in the region of €11,904 per year, and to hold valid health insurance.\", \"items\": [{\"sub\": \"Official proof of subsistence funds for student visa.\", \"label\": \"Blocked Account (Sperrkonto)\", \"value\": \"€11,904 / yr\"}, {\"sub\": \"Earn €13–€16/hr alongside studies and internships.\", \"label\": \"Part-Time Work Permission\", \"value\": \"140 Full Days\"}, {\"sub\": \"Includes campus administrative fee and public transport pass.\", \"label\": \"Semester Contribution\", \"value\": \"€150 – €350\"}], \"title\": \"Costs and Living in Germany\", \"eyebrow\": \"Financial planning\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Key insights on 12-year schooling, English vs German medium, tuition fees, and application timings.\", \"items\": [{\"a\": \"For English-taught or bilingual programmes, yes. Evidence of English proficiency is ordinarily required at the time of application. German-taught programmes require German certification instead.\", \"q\": \"Is an IELTS or TOEFL score required?\"}, {\"a\": \"Yes. According to the DAAD, over one thousand English-taught degree programmes are available across the country, although the number at undergraduate level is smaller than at Master’s level.\", \"q\": \"Are there English-taught Bachelor’s programmes in Germany?\"}, {\"a\": \"It is not a condition of admission where the medium of instruction is wholly English. Nonetheless, some knowledge of German greatly eases everyday life and improves employment prospects.\", \"q\": \"Must I know German to study on an English-taught programme?\"}, {\"a\": \"In most federal states, yes, for undergraduate study. A semester contribution is still payable. Baden-Württemberg charges tuition to most non-EU students, so confirm the position for your university and state.\", \"q\": \"Are tuition fees really waived at public universities?\"}, {\"a\": \"Generally, no. You will need to complete the Studienkolleg, unless you qualify for an exemption or have completed a relevant year of university study.\", \"q\": \"I have completed twelve years of schooling. Can I apply directly?\"}, {\"a\": \"Exemptions are commonly recognised for holders of the International Baccalaureate, for students who have completed a relevant first year of a Bachelor’s programme, and for those who have achieved a qualifying result in JEE Advanced. The final decision rests with the university.\", \"q\": \"Which applicants are exempt from the Studienkolleg?\"}, {\"a\": \"Typically, six to eight semesters (3 to 4 years). The Studienkolleg adds approximately one year for those who require it.\", \"q\": \"How long does a Bachelor’s degree take?\"}, {\"a\": \"Yes. Students may undertake part-time work and internships within the limits set by their residence permit.\", \"q\": \"Can I work while studying?\"}, {\"a\": \"Most universities admit students for the winter semester (beginning in October) and some also for the summer semester (beginning in April). Deadlines vary, so applicants should consult each institution’s website well in advance.\", \"q\": \"When can I apply?\"}], \"title\": \"Undergraduate Admissions FAQ\", \"eyebrow\": \"Frequently asked questions\"}, {\"ctas\": [{\"label\": \"Call me back\", \"action\": \"counselling\"}], \"note\": \"We call within 10 minutes, 8 am to 8 pm IST, Monday to Saturday.\", \"text\": \"Speak with an adviser to evaluate your profile and identify the programmes best suited to your ambitions.\", \"type\": \"cta\", \"title\": \"Begin your German Bachelor’s journey with us\"}]',NULL,NULL,0,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (2,'germany/master','pathway',1,'Master\'s in Germany','Master','1,800+ English-taught Master\'s programmes in Germany. One clear path to your visa, mapped step by step: dMAT, APS, shortlist, apply, visa, fly.','[{\"lead\": \"1,800+ English-taught programmes. One clear path to your visa.\", \"type\": \"hero\", \"chips\": [\"dMAT\", \"APS\", \"Shortlist\", \"Apply\", \"Visa\", \"Fly\"], \"title\": \"Your Master\'s in Germany, mapped step by step.\", \"highlight\": \"mapped step by step.\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Zero German language required for admission\", \"label\": \"English-Taught Master’s\", \"value\": \"1,800+\"}, {\"sub\": \"TUM, RWTH Aachen, KIT, TU Berlin & more\", \"label\": \"Top Public Universities\", \"value\": \"€0 Tuition\"}, {\"sub\": \"Clear route to the EU Blue Card & PR\", \"label\": \"Post-Study Work Visa\", \"value\": \"18 Months\"}, {\"sub\": \"Verified admission rate for mentored applicants\", \"label\": \"Public University Success\", \"value\": \"88 / 100\"}]}, {\"id\": \"journey\", \"type\": \"steps\", \"items\": [{\"desc\": \"Free mocks and eligibility check\", \"title\": \"dMAT\"}, {\"desc\": \"Document checklist and timeline\", \"title\": \"APS\"}, {\"desc\": \"Match from 1,800+ programmes\", \"title\": \"Shortlist\"}, {\"desc\": \"SOP, LOR and uni-assist help\", \"title\": \"Apply\"}, {\"desc\": \"Blocked account and visa file\", \"title\": \"Visa\"}, {\"desc\": \"Arrival checklist\", \"title\": \"Fly\"}], \"title\": \"Your Master\'s, step by step, with us beside you\", \"eyebrow\": \"The journey\"}, {\"id\": \"mock-tests\", \"note\": \"Free with an account. AI marking up to 3 per skill per day.\", \"type\": \"cards\", \"intro\": \"Timed mocks, practice and AI marking in your free dashboard.\", \"items\": [{\"cta\": {\"label\": \"Start dMAT practice\", \"action\": \"evaluation\"}, \"tags\": [\"6 full mocks\", \"119 questions each\"], \"title\": \"dMAT\", \"points\": [\"Timed like the real test\", \"Instant scores and review\", \"Free 2-question sample, no account\"]}, {\"cta\": {\"label\": \"Start German practice\", \"action\": \"counselling\"}, \"tags\": [\"8 mocks\", \"A1 to B2\"], \"title\": \"German\", \"points\": [\"Goethe and telc formats\", \"Listening, reading, writing\", \"AI feedback on writing\"]}, {\"cta\": {\"label\": \"Start IELTS practice\", \"action\": \"evaluation\"}, \"tags\": [\"6 full mocks\", \"Speaking practice\"], \"title\": \"IELTS Academic\", \"points\": [\"Computer-based format\", \"Writing and speaking marked by AI\", \"Band score estimate\"]}], \"style\": \"plain\", \"title\": \"Free mock tests for dMAT, German and IELTS\", \"columns\": 3, \"eyebrow\": \"Free exam prep\"}, {\"id\": \"success-stories\", \"cta\": {\"label\": \"Get Your Profile Evaluated\", \"action\": \"evaluation\"}, \"tone\": \"dark\", \"type\": \"testimonials\", \"intro\": \"5,000+ students guided to tuition-free technical universities and prestigious institutes across Germany.\", \"items\": [{\"meta\": \"Tuition-Free Public\", \"name\": \"Technical University of Munich (TUM)\", \"program\": \"M.Sc. Informatics / Computer Science\", \"university\": \"Technical University of Munich (TUM)\"}, {\"meta\": \"Tuition-Free Public\", \"name\": \"RWTH Aachen University\", \"program\": \"M.Sc. Automotive Engineering\", \"university\": \"RWTH Aachen University\"}, {\"meta\": \"Tuition-Free Public\", \"name\": \"Karlsruhe Institute of Technology (KIT)\", \"program\": \"M.Sc. Electrical Engineering & IT\", \"university\": \"Karlsruhe Institute of Technology (KIT)\"}, {\"meta\": \"Tuition-Free Public\", \"name\": \"TU Berlin\", \"program\": \"M.Sc. Data Engineering\", \"university\": \"TU Berlin\"}, {\"meta\": \"Tuition-Free Public\", \"name\": \"University of Stuttgart\", \"program\": \"M.Sc. Mechanical Engineering\", \"university\": \"University of Stuttgart\"}, {\"meta\": \"Tuition-Free Public\", \"name\": \"FAU Erlangen-Nürnberg\", \"program\": \"M.Sc. Artificial Intelligence\", \"university\": \"FAU Erlangen-Nürnberg\"}], \"title\": \"Real Students. Real Public University Admits.\", \"eyebrow\": \"Verified success stories\"}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Specialized engineering and master’s admissions guidance with complete transparency.\", \"items\": [{\"desc\": \"We prioritize world-ranked TU9 & state universities where you pay €0 tuition instead of costly private commission models.\", \"icon\": \"bank\", \"meta\": \"Admitted to Tuition-Free Public Campuses\", \"badge\": \"88 of 100\", \"title\": \"Public Universities Focus\"}, {\"desc\": \"Master the mandatory dMAT test format with dedicated mock exams and error-free APS document certification verification.\", \"icon\": \"clipboard-check\", \"meta\": \"Fast-Track File Processing\", \"badge\": \"100%\", \"title\": \"Specialized dMAT & APS Support\"}, {\"desc\": \"We map your syllabus credit-by-credit to ensure strict alignment with German university faculties before submitting fees.\", \"icon\": \"journal-check\", \"meta\": \"Due to Missing ECTS Prerequisites\", \"badge\": \"0 Rejections\", \"title\": \"Curriculum Credit-Matching\"}, {\"desc\": \"No anonymous call centers. You work directly with specialists who have guided over 5,000+ admits to Germany.\", \"icon\": \"person-check\", \"meta\": \"Named Expert Mentorship\", \"badge\": \"1-on-1\", \"title\": \"Dedicated Senior Counselors\"}], \"style\": \"icon\", \"title\": \"Why Students Choose EUROPA FUSION\", \"columns\": 2, \"eyebrow\": \"Trusted specialization\"}, {\"id\": \"faq\", \"type\": \"faq\", \"items\": [{\"a\": \"Yes! In 15 out of 16 German federal states, public universities charge €0 tuition fees to both EU and international students. You only pay a nominal semester contribution (€150–€350) which typically includes unlimited regional public transit (Semesterticket).\", \"q\": \"Are German public universities really tuition-free for international Master’s students?\"}, {\"a\": \"Absolutely. Germany offers more than 1,800 Master’s programs taught 100% in English, particularly in Computer Science, AI, Mechanical, Electrical Engineering, Biotechnology, and Business Management. No German language certificate is required for admission to these programs.\", \"q\": \"Can I study a Master’s in Germany completely in English?\"}, {\"a\": \"The dMAT (Digital Masters Admission Test) is required or strongly recommended by leading German universities (such as RWTH Aachen, TUM) and forms part of the APS pathway for Indian applicants in specific STEM disciplines. Our team evaluates your syllabus and provides full mock preparation.\", \"q\": \"Do I need the dMAT for my Master’s application?\"}, {\"a\": \"German universities use the Bavarian formula. A CGPA of 7.0–7.5+ (equivalent to 2.5 or better on the German 1.0–4.0 scale) is competitive for numerous public universities, while top TU9 programs typically look for 8.0+ along with strong credit matching in core subject modules.\", \"q\": \"What is the minimum CGPA required for a Master’s in Germany?\"}, {\"a\": \"Upon graduation from a German university, international students receive an 18-month Job Seeker Visa to find qualified employment. Once you secure a position meeting minimum threshold criteria, you can immediately transition to the EU Blue Card and achieve permanent residency in as little as 21 to 27 months.\", \"q\": \"How does the 18-month post-study work visa and EU Blue Card work?\"}, {\"a\": \"We provide end-to-end guidance: academic credit-matching, profile evaluation, university shortlisting, SOP & academic CV drafting, Uni-Assist / direct portal applications, dMAT preparation, APS filing, blocked account setup, and visa appointment guidance.\", \"q\": \"How does EUROPA FUSION help with the entire application journey?\"}], \"title\": \"Questions Students Ask\", \"eyebrow\": \"Got questions?\"}, {\"ctas\": [{\"label\": \"Call me back\", \"action\": \"counselling\"}], \"note\": \"We call within 10 minutes, 8 am to 8 pm IST, Monday to Saturday.\", \"text\": \"Talk to a counsellor about your Master\'s, from shortlist to visa.\", \"type\": \"cta\", \"title\": \"Ready to start?\"}]',NULL,NULL,1,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (3,'germany/medicine','pathway',1,'Medicine in Germany','Medicine','Study Medicine in Germany: a European medical qualification and clear path to the Approbation, the German licence to practise medicine.','[{\"lead\": \"The Pathway to the Approbation\", \"type\": \"hero\", \"chips\": [\"Admissions\", \"Studienkolleg\", \"Visa\", \"Settlement\"], \"title\": \"Medicine in Germany\", \"eyebrow\": \"EUROPA FUSION\"}, {\"id\": \"invitation\", \"type\": \"intro\", \"title\": \"Your Path to the White Coat Begins in Germany\", \"eyebrow\": \"An invitation to study medicine in Germany\", \"paragraphs\": [\"For more than two centuries, German universities have shaped the discipline of modern medicine. Today, the country remains among the most respected destinations in the world for aspiring physicians, combining academically demanding, clinically oriented training with a publicly funded system that keeps tuition fees at a minimum at most public universities.\", \"For Indian students, the programme offers an uncommon proposition: a European medical qualification of international standing, taught in modern teaching hospitals and simulation centres, at a fraction of the cost associated with private medical education elsewhere. The route is rigorous, and the language requirement is exacting; yet, for the well-prepared candidate, it is a clear and well-regulated path to the <strong>Approbation</strong>, the German licence to practise medicine.\"]}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Single integrated medical course\", \"label\": \"Standard duration of the programme\", \"value\": \"6 yrs 3 mo\"}, {\"sub\": \"Pre-clinical, Clinical, PJ & Approbation\", \"label\": \"Stages of study and examination\", \"value\": \"4\"}, {\"sub\": \"Taught almost exclusively in German\", \"label\": \"German proficiency required\", \"value\": \"C1\"}, {\"sub\": \"Full German medical licence to practice\", \"label\": \"Validity of the Approbation\", \"value\": \"Lifelong\"}]}, {\"id\": \"why\", \"rows\": [[\"Academic reputation\", \"German medical faculties are research-intensive and closely affiliated with university hospitals, giving students early exposure to evidence-based practice.\"], [\"Minimal tuition\", \"Most public universities charge no tuition fees; students pay only a modest semester contribution. A small number of federal states levy fees on non-EU students, so each institution should be verified.\"], [\"Clinical immersion\", \"Training combines lectures, small-group seminars, simulation-based learning and supervised patient contact, culminating in a full practical year.\"], [\"Moderate living costs\", \"Living expenses compare favourably with many other Western European countries, particularly outside the largest metropolitan areas.\"], [\"Lifelong licence\", \"Upon successful completion, the Approbation is granted and, in principle, does not require periodic renewal.\"], [\"Career horizons\", \"Germany’s healthcare system, together with the standing of its qualification across Europe, opens opportunities in clinical practice, research and specialist training.\"]], \"type\": \"table\", \"intro\": \"Six considerations that distinguish German medical education.\", \"title\": \"Why Germany?\", \"columns\": [\"Consideration\", \"What it means for the student\"], \"eyebrow\": \"Distinct advantages\"}, {\"id\": \"eligibility\", \"rows\": [[\"Academic record\", \"A strong Higher Secondary (Class XII) result in the science stream, with Mathematics, Physics, Chemistry, and Biology. Many applicants are expected to present results of approximately 90% or above.\"], [\"University-entrance qualification\", \"Indian Class XII is generally not deemed equivalent to the German Abitur. Candidates therefore normally complete a one-year Studienkolleg (M-Kurs) and pass the Feststellungsprüfung. Holders of qualifications such as the International Baccalaureate may qualify for direct entry.\"], [\"German proficiency\", \"Level C1 of the Common European Framework (for example TestDaF, DSH or an equivalent recognised certificate). Medicine is taught almost exclusively in German.\"], [\"Standardised aptitude test\", \"TestAS, together with any institution-specific entrance assessment (Aufnahmeprüfung) required for Studienkolleg admission.\"], [\"Authentication of documents\", \"An APS certificate (Academic Evaluation Centre, New Delhi) is required of Indian applicants before applying to German institutions.\"], [\"Financial and health cover\", \"Proof of financial resources through a blocked account and valid health insurance are prerequisites for the student visa.\"]], \"type\": \"table\", \"intro\": \"Admission to Medicine is highly competitive, and places for international applicants are limited. The requirements below reflect general institutional expectations.\", \"title\": \"Eligibility and Entry Requirements\", \"columns\": [\"Requirement\", \"Indicative standard\"], \"eyebrow\": \"Admission standards\"}, {\"id\": \"routes\", \"type\": \"timeline\", \"intro\": \"The standard course of study in Medicine extends over <strong>six years and three months</strong>. The total period lengthens depending on the candidate’s starting point: those who require additional German-language preparation and those who must complete the Studienkolleg should plan for a longer overall commitment.\", \"items\": [{\"desc\": \"Medicine 6 y 3 m\", \"label\": \"≈ 6.25 yrs\", \"title\": \"Route A: German-proficient, direct entry (C1 + Abitur Equivalent)\"}, {\"desc\": \"German (1y) → Medicine 6 y 3 m\", \"label\": \"≈ 7.25 yrs\", \"title\": \"Route B: German course before entry (1 yr German + Direct Entry)\"}, {\"desc\": \"German (1y) → M-Kurs (1y) → Medicine 6 y 3 m\", \"label\": \"≈ 8.25 yrs\", \"title\": \"Route C: German + Studienkolleg (M-Kurs) + Medicine (Standard Indian 10+2 pathway)\"}], \"title\": \"Duration of Study & Indicative Entry Routes\", \"eyebrow\": \"Timeline breakdown\"}, {\"text\": \"<strong>Planning note:</strong> Because the admission pathway involves language examinations, certification, university deadlines and visa procedures, candidates are advised to begin preparation at least <strong>12 months</strong>, and ideally <strong>18 to 24 months</strong>, before their intended start date.\", \"type\": \"notice\"}, {\"id\": \"structure\", \"type\": \"cards\", \"intro\": \"Medical education in Germany is a single, integrated course that culminates in state examinations rather than a conventional degree award. It unfolds in four distinct stages.\", \"items\": [{\"meta\": \"4 semesters (2 years)\", \"badge\": \"I\", \"title\": \"Pre-clinical\", \"points\": [\"Anatomy, physiology, biochemistry\", \"First-aid course & nursing service (≈90 days)\", \"Ends: 1st State Examination (Physikum / M1)\"]}, {\"meta\": \"6 semesters (3 years)\", \"badge\": \"II\", \"title\": \"Clinical\", \"points\": [\"Internal medicine, surgery, neurology, sensory systems\", \"Block clinical placements & bedside teaching\", \"Ends: 2nd State Examination (M2)\"]}, {\"meta\": \"48 weeks (PJ)\", \"badge\": \"III\", \"title\": \"Practical Year\", \"points\": [\"16 weeks: Internal medicine\", \"16 weeks: Surgery\", \"16 weeks: Elective specialty of choice\", \"Ends: 3rd State Examination (M3)\"]}, {\"meta\": \"Licence to practise\", \"badge\": \"IV\", \"title\": \"Approbation\", \"points\": [\"Official licence to practice medicine in Germany\", \"Awarded after all three state exams passed\", \"Valid for life without periodic renewal\"]}], \"style\": \"numbered\", \"title\": \"Structure of the Programme\", \"columns\": 2, \"eyebrow\": \"Academic phases\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"The pathway from first enquiry to the first lecture comprises twelve stages, grouped into three phases. EUROPA FUSION supports candidates at each point.\", \"items\": [{\"phase\": \"Phase one — Preparation\", \"title\": \"Profile review & university shortlist\"}, {\"phase\": \"Phase one — Preparation\", \"title\": \"Eligibility check\"}, {\"phase\": \"Phase one — Preparation\", \"title\": \"German language training to B2/C1\"}, {\"phase\": \"Phase one — Preparation\", \"title\": \"TestAS preparation & sitting\"}, {\"phase\": \"Phase two — Application\", \"title\": \"APS certificate application\"}, {\"phase\": \"Phase two — Application\", \"title\": \"Document preparation\"}, {\"phase\": \"Phase two — Application\", \"title\": \"Application submission\"}, {\"phase\": \"Phase two — Application\", \"title\": \"Aufnahmeprüfung invitation\"}, {\"phase\": \"Phase three — Arrival & entry\", \"title\": \"Entrance examination & M-Kurs offer\"}, {\"phase\": \"Phase three — Arrival & entry\", \"title\": \"Blocked account, visa & insurance\"}, {\"phase\": \"Phase three — Arrival & entry\", \"title\": \"M-Kurs Studienkolleg & Feststellungsprüfung\"}, {\"phase\": \"Phase three — Arrival & entry\", \"title\": \"Matriculation in Medicine\"}], \"title\": \"The Admission Journey, Step by Step\", \"eyebrow\": \"Comprehensive roadmap\"}, {\"id\": \"milestones\", \"rows\": [[\"German language\", \"Begin early and aim for a certified level of C1. Language progress is the single greatest determinant of a candidate’s timeline.\"], [\"TestAS\", \"A standardised test of academic aptitude; results are considered by many Studienkollegs and universities.\"], [\"APS certificate\", \"Mandatory authentication of educational credentials for Indian applicants. Processing times vary, so apply promptly.\"], [\"Applications\", \"Submit complete, accurately translated and certified documents before each institution’s deadline. Incomplete files are rarely considered.\"], [\"Blocked account\", \"A dedicated account demonstrating that the student can meet living costs for the first year. The required amount is set by German authorities and revised periodically.\"], [\"Student visa\", \"Applied for at the German diplomatic mission once admission, funds and health insurance are secured.\"], [\"Arrival support\", \"Registration, accommodation, bank account, health insurance and orientation, together with peer guidance from a buddy already studying in Germany.\"]], \"type\": \"table\", \"columns\": [\"Key milestone\", \"Guidance\"]}, {\"id\": \"costs\", \"rows\": [[\"Tuition fees\", \"Generally, none at public universities; certain federal states charge non-EU students. Private institutions charge fees.\"], [\"Semester contribution\", \"A modest administrative charge each semester, often including a regional public-transport ticket (commonly €150–€350).\"], [\"Living costs\", \"Accommodation, food, transport and personal expenses; broadly in line with the blocked-account requirement set for the year.\"], [\"Health insurance\", \"Mandatory throughout the programme; student rates are substantially lower than standard adult rates.\"], [\"Studienkolleg and language\", \"Course fees vary by institution and provider.\"], [\"Part-time work\", \"International students may work a limited number of days each year, though the intensity of medical study means most should not rely on earnings.\"]], \"type\": \"table\", \"intro\": \"Indicative costs for medical aspirants in Germany.\", \"title\": \"Costs and Funding\", \"columns\": [\"Expense\", \"Indicative position\"], \"eyebrow\": \"Financial transparency\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Everything you need to know about the Approbation, language C1, NEET requirements, and admissions.\", \"items\": [{\"a\": \"The standard programme lasts six years and three months. With additional German-language preparation and the Studienkolleg, the overall journey may extend to roughly eight years or more, depending on individual progress.\", \"q\": \"How long does it take to qualify as a doctor in Germany?\"}, {\"a\": \"Almost exclusively in German. Candidates are generally expected to demonstrate level C1 proficiency before commencing the course.\", \"q\": \"In what language is Medicine taught?\"}, {\"a\": \"German universities do not require NEET for admission; selection is based on academic results, language proficiency, and the relevant entrance examinations. However, Indian regulations governing recognition of foreign medical qualifications, and eligibility to practise in India, are set by the National Medical Commission (NMC) and are subject to change. Candidates intending to return to India should verify the current rules before enrolling.\", \"q\": \"Is NEET required for admission to German universities?\"}, {\"a\": \"Requirements differ by institution, but a strong science-stream result, commonly around 90% or above in Class XII, is typically expected given the competitiveness of Medicine.\", \"q\": \"What are the minimum marks required?\"}, {\"a\": \"The Studienkolleg is a preparatory year that bridges the gap between the Indian school-leaving certificate and the German university-entrance qualification. For medical aspirants, the relevant stream is the M-Kurs, concluding with the Feststellungsprüfung. Most Indian applicants must complete it; holders of certain qualifications, such as the International Baccalaureate, may be exempt.\", \"q\": \"What is the Studienkolleg and is it compulsory?\"}, {\"a\": \"Most public universities charge no tuition fees, but students must pay a semester contribution and bear living, insurance and visa-related costs. Some federal states charge tuition to non-EU students, so confirmation with the university is essential.\", \"q\": \"Is education really free?\"}, {\"a\": \"International students may undertake limited part-time work under visa regulations. Given the demands of medical study, students should plan to be financially self-sufficient.\", \"q\": \"Can I work while studying?\"}, {\"a\": \"The Approbation is the state licence to practise medicine in Germany, granted after all three state examinations are passed. It is generally valid for life.\", \"q\": \"What is the Approbation?\"}, {\"a\": \"At least twelve months before the intended start; ideally eighteen to twenty-four months, to allow time for language preparation, APS, TestAS and deadlines.\", \"q\": \"When should I begin applying?\"}, {\"a\": \"No ethical consultancy can. We provide professional guidance, document preparation and strategic planning to maximise the strength of your application.\", \"q\": \"Can EUROPA FUSION guarantee admission?\"}], \"title\": \"Clear Answers for Medical Candidates\", \"eyebrow\": \"Frequently asked questions\"}, {\"ctas\": [{\"label\": \"Call me back\", \"action\": \"counselling\"}], \"note\": \"We call within 10 minutes, 8 am to 8 pm IST, Monday to Saturday.\", \"text\": \"<strong>Speak with an EUROPA FUSION admissions counsellor</strong><br>Our specialist medical admissions desk guides candidates through language benchmarks, M-Kurs selection, TestAS coaching, and official document certifications.\", \"type\": \"cta\", \"title\": \"Begin your medical career in Germany\"}]',NULL,NULL,2,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (4,'germany/studienkolleg','pathway',1,'Studienkolleg in Germany','Studienkolleg','The Studienkolleg bridges the 12-to-13-year schooling gap, prepares you in academic German and leads to the Feststellungsprüfung (FSP) for university admission.','[{\"lead\": \"German universities expect thirteen years of schooling; Indian students complete twelve. The Studienkolleg bridges this gap, prepares you in academic German, and leads directly to the Feststellungsprüfung (FSP) for university admission.\", \"type\": \"hero\", \"title\": \"Studienkolleg: Your Bridge to German Higher Education\", \"eyebrow\": \"Germany · Foundation year\"}, {\"id\": \"what-is\", \"type\": \"intro\", \"title\": \"What Is a Studienkolleg?\", \"eyebrow\": \"Academic foundation\", \"paragraphs\": [\"The <strong>Studienkolleg</strong> is a one-year preparatory institution for international applicants whose secondary-school qualifications do not grant direct access to German higher education. German universities expect <strong>thirteen years of prior schooling</strong>. Indian students normally complete twelve, so the Studienkolleg bridges that gap and leads to the <strong>Feststellungsprüfung (FSP)</strong>, the assessment that confers eligibility for a Bachelor\'s degree.\", \"Beyond closing the schooling gap, the programme helps students adjust to the German academic environment, including the language, the teaching style, and the expectations placed on independent learners.\"]}, {\"type\": \"stats\", \"items\": [{\"sub\": \"2 academic semesters\", \"label\": \"Duration\", \"value\": \"1 Year\"}, {\"sub\": \"Covers 10+2 difference\", \"label\": \"Bridge\", \"value\": \"12 → 13 Year\"}, {\"sub\": \"Bachelor entrance license\", \"label\": \"Assessment\", \"value\": \"FSP\"}]}, {\"id\": \"courses\", \"note\": \"<strong>Choosing the right course matters:</strong> It strictly determines which Bachelor\'s programmes you are legally qualified to apply to after passing the FSP.\", \"rows\": [[\"M-Kurs\", \"Medical & Biological Focus (Medicine / Pharma)\", \"Medical, biological, veterinary and pharmaceutical fields<br><strong>Degrees:</strong> Human Medicine, Dentistry, Pharmacy, Veterinary Medicine, Biology, Biochemistry\"], [\"T-Kurs\", \"Technical & Engineering Focus (Tech & STEM)\", \"Mathematics, engineering and the natural sciences<br><strong>Degrees:</strong> Mechanical, Electrical, Civil Engineering, Computer Science, Physics, Chemistry\"], [\"W-Kurs\", \"Economics & Business Focus (Business & Econ)\", \"Economics, business, law and the social sciences<br><strong>Degrees:</strong> Business Administration (BWL), Economics (VWL), Management, Finance, Social Sciences\"], [\"G-Kurs\", \"Humanities & German Studies Focus (Humanities)\", \"Humanities and German studies<br><strong>Degrees:</strong> History, Philosophy, German Philology, Arts, Literature, Cultural Studies\"], [\"S-Kurs\", \"Languages & Philosophy Focus (Languages)\", \"Languages and philosophy<br><strong>Degrees:</strong> Linguistics, Modern Languages, Translation Studies, International Relations\"]], \"type\": \"table\", \"intro\": \"Students enter through an admission examination, the Aufnahmeprüfung. Once admitted, they follow a specialized course matched to their intended Bachelor\'s field of study.\", \"title\": \"How Admission Works & Course Types\", \"columns\": [\"Course\", \"Focus / Track\", \"Subject Areas & Bachelor Pathways\"], \"eyebrow\": \"Admission exam & specialization\"}, {\"id\": \"exemptions\", \"type\": \"cards\", \"intro\": \"Certain international applicants meet German university qualification criteria without attending a Studienkolleg:\", \"items\": [{\"desc\": \"Valid IB diploma with required German / Mathematics subject levels\", \"title\": \"Holders of the International Baccalaureate (IB)\"}, {\"desc\": \"1 successful year at a recognised Indian college/university (H+ rated on Anabin)\", \"title\": \"Completed One Year of Undergraduate Study\"}, {\"desc\": \"Candidates who cleared the JEE Advanced examination with qualifying ranks\", \"title\": \"Qualified Through JEE Advanced\"}], \"style\": \"check\", \"title\": \"Who May Be Exempt?\", \"columns\": 3, \"eyebrow\": \"Direct entry alternatives\"}, {\"id\": \"advice\", \"cta\": {\"label\": \"Evaluate Exemption vs Studienkolleg\", \"action\": \"evaluation\"}, \"type\": \"intro\", \"title\": \"Our Advice from Experience\", \"eyebrow\": \"Expert guidance\", \"paragraphs\": [\"“Even if you are technically eligible for an exemption, Amratpal advises against skipping the course. The year builds academic communication, independent organisation and presentation skills, all of which make the transition to a rigorous German university far smoother.”\"]}, {\"id\": \"campuses\", \"type\": \"cards\", \"intro\": \"Each institution type has its own application process, fees, and intake schedule, so it is worth comparing options early.\", \"items\": [{\"desc\": \"University-affiliated Studienkollegs focusing deeply on theoretical rigor, leading to research universities nationwide.\", \"badge\": \"Universitätskollegs\", \"title\": \"Technical Universities (TU / Uni)\"}, {\"desc\": \"Practice-oriented preparatory tracks tied directly to hands-on engineering, business, and industry-partnered degrees.\", \"badge\": \"FH-Kollegs\", \"title\": \"Universities of Applied Sciences (Fachhochschulen / HAW)\"}, {\"desc\": \"Independent accredited institutes offering structured tuition-based pathways, personalized entrance coaching, and flexible intakes.\", \"badge\": \"Private Kollegs\", \"title\": \"Private Institutes\"}], \"style\": \"plain\", \"title\": \"Where Are Studienkollegs Located?\", \"columns\": 3, \"eyebrow\": \"Campus types\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Everything you need to know about the 1-year bridge, the FSP examination, and course selection.\", \"items\": [{\"a\": \"German universities require thirteen years of schooling. Indian students typically complete twelve (10+2 system), so the Studienkolleg covers the missing year and prepares them academically for higher education in Germany.\", \"q\": \"Why do Indian students need a Studienkolleg?\"}, {\"a\": \"The FSP (university qualification assessment exam) is the final assessment at the end of the Studienkolleg. Passing it confers official eligibility to apply for a Bachelor\'s degree across German universities.\", \"q\": \"What is the Feststellungsprüfung (FSP)?\"}, {\"a\": \"The Aufnahmeprüfung is the competitive admission examination you must pass to enter the Studienkolleg. It usually assesses your German proficiency (B1/B2) and basic mathematics or subject fundamentals.\", \"q\": \"What is the Aufnahmeprüfung?\"}, {\"a\": \"The Studienkolleg programme lasts one year (comprising 2 full academic semesters).\", \"q\": \"How long is the programme?\"}, {\"a\": \"Match the course to your intended Bachelor\'s subject. For example, choose the T-Kurs for engineering and STEM, the W-Kurs for business and economics, the M-Kurs for medicine or pharmacy, G-Kurs for humanities, and S-Kurs for languages.\", \"q\": \"How do I choose between the M, T, W, G and S courses?\"}, {\"a\": \"Some applicants may be exempt, including IB diploma holders, students who completed 1 year of undergraduate study at a recognised Indian university, and JEE Advanced qualifiers. Even so, Amratpal and our expert team advise attending, as the foundation builds vital academic language and communication skills that help you succeed at university.\", \"q\": \"Can I skip the Studienkolleg?\"}, {\"a\": \"Studienkollegs are attached to technical universities (TU), universities of applied sciences (Fachhochschulen), and private institutes across Germany.\", \"q\": \"Where can I study at a Studienkolleg?\"}, {\"a\": \"Passing the FSP confers formal legal eligibility for Bachelor\'s study in Germany, but admission remains competitive for Numerus Clausus (NC) programmes. You must still apply to universities and meet their individual grade and cut-off requirements.\", \"q\": \"Does passing the FSP guarantee a place at a university?\"}], \"title\": \"Frequently Asked Questions (FAQ)\", \"eyebrow\": \"Clear answers\"}, {\"ctas\": [{\"label\": \"Call me back\", \"action\": \"counselling\"}], \"note\": \"We call within 10 minutes, 8 am to 8 pm IST, Monday to Saturday.\", \"text\": \"Planning your route to Germany can feel complicated, from choosing the right course (M, T, W, G, S) to preparing for the Aufnahmeprüfung. Reach out to our team for personalised support at every step.\", \"type\": \"cta\", \"title\": \"Planning your route to Germany?\", \"eyebrow\": \"Need guidance?\"}]',NULL,NULL,3,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (5,'study-in-austria','country',2,'Study in Austria','Austria','Pursue an affordable, world-class European degree in Vienna, Graz, Innsbruck and beyond, with EUROPA FUSION guiding every step of your journey.','[{\"ctas\": [{\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}, {\"label\": \"Book Consultation\", \"action\": \"counselling\"}], \"lead\": \"Pursue an affordable, world-class European degree in Vienna, Graz, Innsbruck and beyond, with EUROPA FUSION guiding every step of your journey.\", \"type\": \"hero\", \"title\": \"Where Academic Rigour Meets Alpine Quality of Life\", \"eyebrow\": \"Study in Austria\", \"highlight\": \"Alpine Quality of Life\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"At world-ranked public universities\", \"label\": \"Annual tuition for non-EU\", \"value\": \"≈ €1,500\"}, {\"sub\": \"Winter (October) & Summer (March)\", \"label\": \"Main intakes each year\", \"value\": \"2\"}, {\"sub\": \"Bachelor’s + Master’s under Bologna\", \"label\": \"Years to degree\", \"value\": \"3 + 2\"}, {\"sub\": \"Pathway for graduates seeking skilled work\", \"label\": \"Red-White-Red Card\", \"value\": \"RWR\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Austria combines high academic standards with an enviable quality of life. Situated at the centre of Europe, it offers international students rigorous research environments and tuition costs that compare favourably with other global study hubs.\", \"items\": [{\"desc\": \"Public university tuition remains exceptionally modest (≈ €726.72/semester), even for international students from outside the EU/EEA.\", \"icon\": \"piggy-bank\", \"title\": \"Outstanding affordability\"}, {\"desc\": \"Austrian universities are globally recognized in engineering, business, computer science, natural sciences, music, medicine and the arts.\", \"icon\": \"globe-europe-africa\", \"title\": \"Academic and professional depth\"}, {\"desc\": \"Vienna is consistently ranked among the #1 most liveable cities in the world, while Graz, Innsbruck and Linz offer vibrant student alternatives.\", \"icon\": \"shield-check\", \"title\": \"Exceptional quality of life\"}, {\"desc\": \"Graduates may apply for the Red-White-Red Card to seek skilled employment, with degrees fully portable across Europe.\", \"icon\": \"briefcase\", \"title\": \"A route to a career in Europe\"}, {\"desc\": \"Situated in the heart of Europe, Austria provides immediate access to Germany, Switzerland, Italy, and Central European business hubs.\", \"icon\": \"globe-europe-africa\", \"title\": \"A European gateway\"}], \"style\": \"icon\", \"title\": \"A World-Class Education at an Exceptional Value\", \"columns\": 3, \"eyebrow\": \"Why Austria\"}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"The following institutions represent key destinations available to EUROPA FUSION students.\", \"items\": [{\"city\": \"Vienna\", \"desc\": \"Austria’s largest and oldest university, offering an exceptionally wide spectrum of disciplines across sciences, humanities, law and economics.\", \"name\": \"University of Vienna\", \"type\": \"Public University\"}, {\"city\": \"Vienna\", \"desc\": \"A premier European centre for engineering, computer science, architecture and mathematics, with close ties to Austrian industry.\", \"name\": \"TU Wien\", \"type\": \"Technical University\"}, {\"city\": \"Vienna\", \"desc\": \"One of Europe’s foremost triple-accredited business universities, recognized internationally for management, finance and business law.\", \"name\": \"WU Vienna (Vienna University of Economics & Business)\", \"type\": \"Business University\"}, {\"city\": \"Graz\", \"desc\": \"Distinguished in engineering and natural sciences, with strong industry partnerships in automotive mobility, energy and semiconductors.\", \"name\": \"TU Graz\", \"type\": \"Technical University\"}, {\"city\": \"Graz\", \"desc\": \"A comprehensive research university known for law, social sciences, natural sciences, biotechnology and sustainability research.\", \"name\": \"University of Graz\", \"type\": \"Public University\"}, {\"city\": \"Innsbruck\", \"desc\": \"Renowned for physics, alpine and climate research, environmental sciences, sports science, medicine and the humanities.\", \"name\": \"University of Innsbruck\", \"type\": \"Public University\"}, {\"city\": \"Linz\", \"desc\": \"Combines cutting-edge technology, artificial intelligence, software engineering, business and law within an innovation-focused campus.\", \"name\": \"Johannes Kepler University Linz (JKU)\", \"type\": \"Public University\"}, {\"city\": \"Innsbruck\", \"desc\": \"A practice-oriented institution offering management, entrepreneurship, technology and tourism programmes with direct employer links.\", \"name\": \"MCI | The Entrepreneurial School\", \"type\": \"Applied Sciences\"}], \"title\": \"Distinguished Institutions in Austria\", \"eyebrow\": \"Featured universities\"}, {\"id\": \"programmes\", \"rows\": [[\"Bachelor’s degree\", \"3 years (6 sem)\", \"180\", \"Requires recognised Matura equivalent; wide range of German-taught programmes and selective English options.\"], [\"Master’s degree\", \"1.5–2 years\", \"90–120\", \"The widest choice of English-taught programmes, particularly in technology, business, AI and sciences.\"], [\"Diploma programmes\", \"4–6 years\", \"240–360\", \"Medicine (MedAT entrance test), Dentistry and Law; integrated single-cycle professional degrees.\"], [\"Doctorate (PhD)\", \"3–4 years\", \"—\", \"Research-intensive study, often with salaried employment-style contracts at the university or research institutes.\"], [\"University of Applied Sciences (FH)\", \"3 yrs (BSc) + 2 yrs (MSc)\", \"180 + 120\", \"Practice-oriented study with mandatory industry internships; selective entry with tests or interviews.\"], [\"Private university programmes\", \"Varies\", \"Varies\", \"Smaller cohorts and high faculty ratio; English-taught programmes with institution-set tuition fees.\"]], \"type\": \"table\", \"chips\": [\"Engineering and Technology\", \"Business, Economics and Finance\", \"Computer Science and Artificial Intelligence\", \"Medicine and Life Sciences\", \"Natural Sciences\", \"Architecture and Design\", \"Music and Performing Arts\", \"Tourism and Hospitality Management\"], \"intro\": \"Austrian higher education follows the Bologna three-cycle model with public universities, Fachhochschulen (FH), and medical diplomas.\", \"title\": \"Programmes and Qualifications in Austria\", \"columns\": [\"Qualification\", \"Duration\", \"Credits (ECTS)\", \"Notes & Focus\"], \"eyebrow\": \"Academic pathways\", \"chips_title\": \"Popular fields of study in Austria\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 1500, \"min\": 1500, \"label\": \"Public university tuition, non-EU (per year)\", \"value\": \"≈ €1,500\"}, {\"max\": 1450, \"min\": 730, \"label\": \"University of Applied Sciences tuition (per year)\", \"value\": \"≈ €730 - €1,450\"}, {\"max\": 15600, \"min\": 11400, \"label\": \"Living costs (per year)\", \"value\": \"€11,400 - €15,600\"}, {\"max\": 15700, \"min\": 8670, \"label\": \"Proof of funds for permit (per year, by age)\", \"value\": \"€8,670 (under 24) - €15,700 (24+)\"}], \"type\": \"costs\", \"cards\": [{\"desc\": \"Scholarship and mobility programmes administered by Austria’s national agency for international academic exchange.\", \"title\": \"OeAD Scholarships\"}, {\"desc\": \"A monthly funding grant supporting international students and young researchers, particularly at Master’s and PhD level.\", \"title\": \"Ernst Mach Grant\"}, {\"desc\": \"Performance bursaries and EU-funded Erasmus Mundus joint Master’s degree grants.\", \"title\": \"University Merit Awards & Erasmus\"}], \"intro\": \"A clear view of costs allows you to plan with confidence. Indicative annual ranges in euros:\", \"title\": \"Understanding the Investment in Austria\", \"eyebrow\": \"Fees & funding\", \"scale_max\": 20000, \"cards_title\": \"Scholarships & funding\", \"chart_title\": \"Indicative annual investment in Austria\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"EUROPA FUSION offers a structured, transparent process so that each stage is handled with care and precision.\", \"items\": [{\"desc\": \"Academic record, career goals, budget and preferred city are reviewed to define a realistic shortlist.\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Courses are matched to your profile, with attention to language of instruction, admission procedures and deadlines.\", \"title\": \"Programme & university selection\"}, {\"desc\": \"Transcripts, certificates, language proof, CV, motivation letter and passport are prepared and submitted directly or via portals.\", \"title\": \"Documents & application\"}, {\"desc\": \"Where required, preparation for entrance tests, interviews, or Austrian foundation-course (Vorstudienlehrgang) prerequisites.\", \"title\": \"Admission assessment\"}, {\"desc\": \"Admission is confirmed and academic qualifications are evaluated for equivalence by the university.\", \"title\": \"Offer & credential recognition\"}, {\"desc\": \"Preparation of the Austrian Student Residence Permit (Aufenthaltsbewilligung Student) file, including proof of funds and accommodation.\", \"title\": \"Residence permit for study\"}, {\"desc\": \"Enrolment formalities, Meldezettel (address registration), Austrian student insurance, and city orientation.\", \"title\": \"Arrival & settling in\"}], \"title\": \"From Enquiry to Enrolment\", \"eyebrow\": \"Your admission journey\"}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"cards\", \"intro\": \"We believe a student’s journey abroad should be guided with the same rigour as the education it leads to.\", \"items\": [{\"desc\": \"Personalised shortlisting and strategy from first enquiry to offer.\", \"icon\": \"compass\", \"title\": \"Admissions Counselling\"}, {\"desc\": \"Careful preparation of statements of purpose, CVs and supporting documents.\", \"icon\": \"file-earmark-text\", \"title\": \"Application Excellence\"}, {\"desc\": \"Support with OeAD, Ernst Mach and university merit scholarship options.\", \"icon\": \"award\", \"title\": \"Scholarship Guidance\"}, {\"desc\": \"Structured assistance with Austrian student residence permit documentation and financial evidence.\", \"icon\": \"passport\", \"title\": \"Residence Permit Support\"}, {\"desc\": \"Guidance on student dormitories (OeAD housing) and private apartments in Vienna and Graz.\", \"icon\": \"house-door\", \"title\": \"Accommodation Support\"}, {\"desc\": \"Briefings before you fly and continued support after you arrive in Austria.\", \"icon\": \"airplane\", \"title\": \"Pre-Departure & Beyond\"}], \"style\": \"icon\", \"title\": \"Your Partner for the Journey\", \"columns\": 3, \"eyebrow\": \"Why EUROPA FUSION\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Common questions about studying and settling in Austria.\", \"items\": [{\"a\": \"Yes. Austria offers a growing number of English-taught Master’s programmes, particularly in technology, business, economics and the sciences. Most Bachelor’s programmes at public universities are taught in German, so the language of instruction must be confirmed for every course.\", \"q\": \"Can I study in Austria in English?\"}, {\"a\": \"For German-taught programmes, certified proficiency (such as Goethe-Zertifikat or TestDaF, typically B2 or C1) is required. For English-taught programmes it is not mandatory, but even basic German greatly improves daily life, part-time work and career prospects.\", \"q\": \"Do I need to know German?\"}, {\"a\": \"Austria offers some of Europe’s most reasonable tuition. Non-EU students at public universities currently pay around €726.72 per semester (≈ €1,453/year) plus a small student union (ÖH) fee. Living costs typically range between €950 and €1,300 per month.\", \"q\": \"How much does it cost to study in Austria?\"}, {\"a\": \"The main intake is the winter semester beginning in October, with a smaller summer intake beginning in March. Non-EU applicants face earlier deadlines because the residence permit process runs in parallel, so applications should begin 9 to 12 months in advance.\", \"q\": \"When are the intakes and application deadlines?\"}, {\"a\": \"Most English-taught programmes request proof of proficiency such as IELTS (6.0–7.0) or TOEFL (80–100), depending on the university and program.\", \"q\": \"What are the English-language requirements?\"}, {\"a\": \"Applicants must demonstrate sufficient funds for their stay. Official figures are approximately €722.58 per month for students under 24 (≈ €8,670/year) and €1,308.39 per month for students aged 24 or over (≈ €15,700/year).\", \"q\": \"How much money must I show for the residence permit?\"}, {\"a\": \"Yes. Opportunities include OeAD-administered programmes, the Ernst Mach Grant, merit awards from individual universities and selected Erasmus Mundus joint Master’s programmes.\", \"q\": \"Are scholarships available for international students?\"}, {\"a\": \"Non-EU students may work part-time (up to 20 hours per week) subject to an employment permit (Beschäftigungsbewilligung) issued by the AMS.\", \"q\": \"Can I work while studying in Austria?\"}, {\"a\": \"Graduates of Austrian universities can apply for a 12-month extension of their student residence permit to seek employment, and then transition to the Red-White-Red Card (Rot-Weiß-Rot-Karte).\", \"q\": \"Can I stay in Austria after graduating?\"}, {\"a\": \"Typically: passport, academic transcripts and degree certificates (with apostille/legalisation), language-test results, CV, motivation letter, proof of financial means, proof of accommodation and Austrian-compliant health insurance.\", \"q\": \"What documents will I need?\"}, {\"a\": \"We assist at every stage: profile assessment, university shortlisting, German/English document review, entrance assessment guidance, Aufenthaltsbewilligung permit filing, and accommodation booking.\", \"q\": \"How does EUROPA FUSION support my application?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"FAQ\"}, {\"ctas\": [{\"label\": \"Book Free Consultation\", \"action\": \"counselling\"}, {\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}], \"text\": \"Speak with a EUROPA FUSION counsellor for a personalised university shortlist and a clear roadmap to your offer letter.\", \"type\": \"cta\", \"title\": \"Begin Your Austrian Chapter\"}]',NULL,NULL,4,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (6,'study-in-finland','country',4,'Study in Finland','Finland','Finland: where Nordic excellence meets your global ambition. Rigorous scholarship, industry-linked research and a secure future in Europe with EUROPA FUSION.','[{\"lead\": \"EUROPA FUSION | Abroad Education Consultants\", \"type\": \"hero\", \"title\": \"The Nordic Advantage\", \"eyebrow\": \"Study in Finland\", \"tagline\": \"World-class education • Innovation-led research • A secure future in Europe\", \"highlight\": \"Nordic Advantage\"}, {\"cta\": {\"label\": \"Book Consultation\", \"action\": \"counselling\"}, \"type\": \"intro\", \"title\": \"Finland: Where Nordic Excellence Meets Your Global Ambition\", \"paragraphs\": [\"Finland has earned a distinguished reputation for scholarship that is rigorous without being rarefied: universities of international standing, research woven closely into industry, and a society consistently regarded among the most stable, safe and content in the world. For the discerning applicant, it offers a rare combination of academic depth, professional opportunity and quality of life, within the Schengen Area and at the heart of Europe’s innovation economy.\", \"Begin your journey: book a complimentary consultation with EUROPA FUSION\"]}, {\"type\": \"stats\", \"items\": [{\"label\": \"Population\", \"value\": \"5.6 M\"}, {\"sub\": \"(Autumn • Spring)\", \"label\": \"Intakes a year\", \"value\": \"2\"}, {\"sub\": \"right while studying\", \"label\": \"Average weekly work\", \"value\": \"30 hrs\"}, {\"sub\": \"permit\", \"label\": \"Post-study job-search\", \"value\": \"2 yrs\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Finnish higher education is built on trust, autonomy and applied learning. Its distinguishing strengths include:\", \"items\": [{\"desc\": \"A binary system of research universities and universities of applied sciences (UAS), offering a wide range of Bachelor’s and Master’s degrees taught entirely in English.\", \"title\": \"Academic standing\"}, {\"desc\": \"Particular strength in technology, ICT and artificial intelligence, engineering, forestry and bioeconomy, life sciences, design, architecture, business and education.\", \"title\": \"Disciplines of distinction\"}, {\"desc\": \"Close links between universities and companies, innovation hubs and start-up ecosystems, with ample opportunity for projects, internships and thesis collaboration.\", \"title\": \"Research integrated with industry\"}, {\"desc\": \"Graduates may apply for a permit to remain in Finland for up to two years to seek employment or establish a business.\", \"title\": \"A pathway beyond graduation\"}, {\"desc\": \"Students holding a residence permit for studies may work, in any field, for an average of 30 hours per week.\", \"title\": \"Work alongside study\"}, {\"desc\": \"Finland is repeatedly ranked among the world’s happiest countries, with low corruption, strong public services and a deep culture of equality.\", \"title\": \"Safety and wellbeing\"}, {\"desc\": \"Residing in Finland, a Schengen member, brings straightforward travel across much of the continent.\", \"title\": \"Gateway to Europe\"}], \"style\": \"numbered\", \"title\": \"Why Study in Finland?\", \"columns\": 3, \"eyebrow\": \"Distinguishing strengths\"}, {\"id\": \"eligibility\", \"rows\": [[\"Bachelor’s degree\", \"Completion of 12 years of schooling (Class XII or equivalent)\", \"Generally, 55% and above; selective programmes require more. Duration: typically, 3–4 years.\"], [\"Master’s degree\", \"A recognised Bachelor’s degree of 3–4 years in a relevant discipline\", \"Generally, 55% and above; selective programmes require more. Duration: typically, 1–2 years.\"]], \"type\": \"table\", \"intro\": \"Each institution sets its own entry standards, and competitive programmes may expect considerably more than the minimum. As a general guide, applicants should satisfy the following.\", \"title\": \"Eligibility Criteria\", \"columns\": [\"Level\", \"Academic requirement\", \"Indicative standard and duration\"], \"eyebrow\": \"Entry standards\"}, {\"type\": \"checklist\", \"items\": [\"Be at least 18 years of age.\", \"Demonstrate English proficiency through IELTS, PTE, TOEFL, or an equivalent test; most programmes ask for an overall IELTS score of around 6.0–6.5, although requirements differ by institution.\", \"Receive an offer of admission from a Finnish higher education institution.\", \"Demonstrate sufficient funds for living costs and, where applicable, tuition.\", \"Hold comprehensive health insurance meeting the Finnish Immigration Service (Migri) requirements.\", \"Where required by the programme, submit a motivation letter, portfolio, references or entrance-examination results.\"], \"title\": \"In addition, applicants are expected to:\", \"columns\": 1}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"Finland’s universities are public institutions, each with a distinct academic character. A representative selection for international applicants is given below.\", \"items\": [{\"city\": \"Helsinki\", \"desc\": \"Finland’s oldest and largest university; broad strength across the sciences, humanities, law and medicine\", \"name\": \"University of Helsinki\"}, {\"city\": \"Espoo / Helsinki\", \"desc\": \"Technology, design, architecture and business, with a strong entrepreneurial culture\", \"name\": \"Aalto University\"}, {\"city\": \"Turku\", \"desc\": \"Biosciences, law, economics, maritime studies and digital technology\", \"name\": \"University of Turku\"}, {\"city\": \"Tampere\", \"desc\": \"Engineering, health sciences, social sciences and information technology\", \"name\": \"Tampere University\"}, {\"city\": \"Oulu\", \"desc\": \"ICT, wireless technology, engineering, health and Arctic research\", \"name\": \"University of Oulu\"}, {\"city\": \"Jyväskylä\", \"desc\": \"Education, humanities, sport and health sciences, and information technology\", \"name\": \"University of Jyväskylä\"}, {\"city\": \"Lappeenranta\", \"desc\": \"Energy, sustainability, engineering and business technology\", \"name\": \"LUT University\"}, {\"city\": \"Various\", \"desc\": \"Practice-oriented degrees in engineering, business, nursing, hospitality and the creative industries\", \"name\": \"Universities of Applied Sciences (e.g. Metropolia, Haaga-Helia, Tampere UAS)\"}], \"title\": \"Distinguished Institutions\", \"eyebrow\": \"Academic reputation\"}, {\"id\": \"intakes\", \"note\": \"Many English-taught Bachelor’s and Master’s programmes are applied for through the national Studyinfo joint application, which typically runs in January for the following autumn; some institutions use their own portals and deadlines. Popular programmes fill quickly, and early preparation of transcripts, language scores and funding documents is strongly advised.\", \"rows\": [[\"Autumn (August–September)\", \"Principal intake\", \"The majority of degree programmes begin here. Applications generally open the previous winter.\"], [\"Spring (January)\", \"Selected programmes\", \"A smaller number of programmes admit students in January.\"]], \"type\": \"table\", \"title\": \"Intakes and Academic Calendar\", \"columns\": [\"Intake\", \"Status\", \"Notes\"], \"eyebrow\": \"Application timelines\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 18000, \"min\": 4000, \"label\": \"Tuition fees (non-EU/EEA)\", \"value\": \"Typically, between €4,000 and €18,000 per year, depending on institution and programme\"}, {\"max\": 600, \"min\": 600, \"label\": \"Residence permit application fee\", \"value\": \"Approximately €600 online (higher for paper applications); fees are revised periodically\"}, {\"max\": 9600, \"min\": 9600, \"label\": \"Proof of funds (living costs)\", \"value\": \"€800 per month; €9,600 for a 12-month permit (approximately ₹10–11 lakh)\"}, {\"max\": 1400, \"min\": 900, \"label\": \"Typical monthly expenditure\", \"value\": \"Approximately €900–1,400, depending on city and lifestyle\"}], \"type\": \"costs\", \"intro\": \"Students from outside the EU/EEA are required to pay tuition fees for English-taught Bachelor’s and Master’s programmes. Finland remains comparatively competitive for the quality offered, and many institutions provide substantial scholarships.\", \"title\": \"The Cost of Studying in Finland\", \"eyebrow\": \"Financial outlay\", \"scale_max\": 18000, \"chart_title\": \"Indicative amount\"}, {\"id\": \"living-costs\", \"note\": \"Migri’s minimum proof of funds: €800 per month (€9,600 for 12 months)\", \"rows\": [{\"max\": 650, \"min\": 350, \"label\": \"Accommodation\", \"value\": \"€350 – 650\"}, {\"max\": 350, \"min\": 250, \"label\": \"Food\", \"value\": \"€250 – 350\"}, {\"max\": 60, \"min\": 30, \"label\": \"Transport\", \"value\": \"€30 – 60\"}, {\"max\": 100, \"min\": 40, \"label\": \"Insurance & health\", \"value\": \"€40 – 100\"}, {\"max\": 300, \"min\": 150, \"label\": \"Study materials & leisure\", \"value\": \"€150 – 300\"}], \"type\": \"costs\", \"intro\": \"≈ €1,100 typical monthly budget (mid-range estimate)\", \"title\": \"Indicative monthly living costs\", \"scale_max\": 700, \"chart_title\": \"Indicative monthly living costs\"}, {\"text\": \"<strong>A point of clarification:</strong> Many sources describe Finnish education as free. That is true only for EU/EEA citizens and for doctoral study. International students from India should plan for tuition fees and for the funds required by Migri.\", \"type\": \"notice\"}, {\"id\": \"scholarships\", \"note\": \"Scholarship applications usually form part of, or run alongside, the admission application, and deadlines are firm.\", \"type\": \"cards\", \"items\": [{\"desc\": \"Awarded by universities based on academic merit, often covering part or all of the fee.\", \"icon\": \"award\", \"title\": \"Institutional tuition-fee scholarships\"}, {\"desc\": \"Offered by a limited number of institutions to top international candidates.\", \"icon\": \"cash-coin\", \"title\": \"Living-cost scholarships\"}, {\"desc\": \"Including Finnish national and Nordic programmes and, in some cases, home-country schemes.\", \"icon\": \"globe-europe-africa\", \"title\": \"External funding\"}, {\"desc\": \"Structured financing with guidance available through EUROPA FUSION’s dedicated loan assistance service.\", \"icon\": \"bank\", \"title\": \"Education loans from Indian banks\"}], \"style\": \"icon\", \"title\": \"Scholarships and Financial Support\", \"columns\": 2, \"eyebrow\": \"Funding options\"}, {\"id\": \"journey\", \"note\": \"<strong>Timing advice:</strong> Begin the permit application immediately after receiving your offer. Document verification, corrections and card issuance take longer than most applicants expect, and a late permit can mean a missed start date.\", \"type\": \"steps\", \"intro\": \"A structured 8-step journey for international scholars targeting Finland\", \"items\": [{\"tag\": \"Programmes & universities\", \"desc\": \"Research universities and degree programmes to identify the most suitable fit.\", \"title\": \"Shortlist\"}, {\"tag\": \"Studyinfo / university portal\", \"desc\": \"Apply through Studyinfo or the university’s own portal, ensuring all academic and language requirements are met.\", \"title\": \"Apply\"}, {\"tag\": \"Admission letter\", \"desc\": \"On receiving an offer of admission, accept the place and begin assembling documents for the residence permit.\", \"title\": \"Offer\"}, {\"tag\": \"Fee payment or funds evidence\", \"desc\": \"Settle the tuition fee. Where the university requires payment before the permit application, attach proof of payment; where payment is due after arrival, you must show the tuition amount in your account in addition to the living funds. Funds set aside for living costs cannot be counted twice.\", \"title\": \"Tuition\"}, {\"tag\": \"Enter Finland application\", \"desc\": \"Complete the residence permit application online through Migri’s Enter Finland service.\", \"title\": \"Permit\"}, {\"tag\": \"Embassy / VFS biometrics\", \"desc\": \"Attend an appointment at the Finnish embassy or visa application centre to verify identity and give biometric data.\", \"title\": \"Identity\"}, {\"tag\": \"Typically 1–3 months\", \"desc\": \"Await the decision, which commonly takes one to three months. Progress can be tracked online.\", \"title\": \"Decision\"}, {\"tag\": \"Settle in before term begins\", \"desc\": \"On approval, arrange travel, accommodation and insurance, and arrive in good time before term.\", \"title\": \"Arrive\"}], \"title\": \"Your Route from Enquiry to Arrival\", \"eyebrow\": \"Admission roadmap\"}, {\"id\": \"permit\", \"type\": \"cards\", \"intro\": \"Non-EU/EEA nationals planning to study in Finland for more than 90 days must obtain a residence permit for studies from the Finnish Immigration Service (Migri). The permit may be granted for the entire duration of the degree.\", \"items\": [{\"desc\": \"A formal confirmation of a study place from an accredited Finnish higher education institution.\", \"title\": \"Offer of admission\"}, {\"desc\": \"With validity covering the planned period of study across Europe.\", \"title\": \"Valid passport\"}, {\"desc\": \"At least €800 per month in the applicant’s own bank account at the time of application; origin of funds must be verifiable.\", \"title\": \"Proof of funds\"}, {\"desc\": \"Evidence of fees paid, a formal scholarship award, or additional funds covering the fee.\", \"title\": \"Tuition evidence\"}, {\"desc\": \"For studies of 2+ years, cover of at least €40,000 for medical expenses; for shorter studies, at least €120,000.\", \"title\": \"Comprehensive health insurance\"}, {\"desc\": \"Official certificates and transcripts supporting your qualifications, apostilled/attested where applicable.\", \"title\": \"Academic records\"}, {\"desc\": \"Fingerprints and photograph at the Finnish embassy/VFS centre, and payment of the processing fee.\", \"title\": \"Biometrics and fee\"}], \"style\": \"check\", \"title\": \"Residence Permit for Studies: Requirements\", \"columns\": 3, \"eyebrow\": \"Migri immigration guidelines\"}, {\"id\": \"permit-categories\", \"rows\": [[\"Residence permit for studies\", \"For degree students; granted for the length of the studies\"], [\"Residence permits to look for work or start a business\", \"For graduates of Finnish institutions; up to two years\"], [\"Work-based residence permit\", \"For those holding a qualifying job offer or employment\"], [\"Family-based permit\", \"For family members of persons residing in Finland\"], [\"Permanent residence permit\", \"For those who meet the residence and other criteria set by law\"]], \"type\": \"table\", \"title\": \"Categories of permit\", \"columns\": [\"Permit\", \"Purpose\"]}, {\"id\": \"working\", \"type\": \"split\", \"title\": \"Working During and After Your Studies\", \"columns\": [{\"title\": \"During study\", \"paragraphs\": [\"Holders of a residence permit for studies may work in paid employment in any field for an average of <strong>30 hours per week</strong>. The first permit application cannot rely on anticipated earnings, so funds must be demonstrated independently. Part-time work in hospitality, retail, logistics, research assistance, and campus roles is common, and Finnish language skills considerably broaden the options.\"]}, {\"title\": \"After graduation\", \"paragraphs\": [\"Graduates may apply for a residence permit to look for work or start a business, valid for <strong>up to two years</strong>. The application must be made before the study permit expires, or within five years of its expiry. Proof of funds of €800 per month is required.\"]}], \"eyebrow\": \"Career & settlement\"}, {\"note\": \"Permanent residence has historically required about four years of continuous residence on qualifying permits; 2026 reforms have tightened the criteria.\", \"type\": \"steps\", \"items\": [{\"desc\": \"Residence permit for studies\", \"title\": \"Degree studies\"}, {\"desc\": \"Up to 2 years after graduation\", \"title\": \"Job-search permit\"}, {\"desc\": \"Qualified employment\", \"title\": \"Work-based permit\"}, {\"desc\": \"Subject to current Migri rules\", \"title\": \"Permanent residence\"}], \"title\": \"From classroom to career to residence\"}, {\"type\": \"checklist\", \"items\": [\"Convert to a work-based permit upon securing qualified employment.\", \"Establish a start-up or business using the post-study permit, supported by Finland’s active entrepreneurial ecosystem.\", \"Work toward permanent residence. Time spent studying has counted toward the continuous-residence period, but Finland tightened its permanent residence rules in 2026, including residence period and language expectations, so applicants should confirm the current criteria with Migri.\"], \"title\": \"Routes to long-term residence:\", \"columns\": 1}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"checklist\", \"intro\": \"From the first conversation to your arrival in Finland, we provide structured, end-to-end guidance.\", \"title\": \"How Europa Fusion Supports You\", \"groups\": [{\"items\": [\"Educational counselling and decision-making\", \"Prerequisite exams (IELTS, PTE)\", \"Pre-visa guidance and documentation\", \"Education loan assistance\", \"Accommodation assistance\", \"Airport pickup and drop-off facilities\"], \"title\": \"Counselling and Admissions\"}, {\"items\": [\"Scholarship guidance\", \"Documentation and admission support\", \"Health insurance guidance\", \"Flight bookings\", \"Pre-departure briefing and support\", \"Post-arrival guidance\"], \"title\": \"Travel and Settlement\"}], \"columns\": 2, \"eyebrow\": \"End-to-end guidance\"}, {\"id\": \"faq\", \"type\": \"faq\", \"items\": [{\"a\": \"Most English-taught programmes require evidence of English proficiency, commonly an overall IELTS score of 6.0–6.5, though some accept alternative tests or waive the requirement. Check the criteria for each programme.\", \"q\": \"Do I need IELTS to study in Finland?\"}, {\"a\": \"No. Tuition is charged to non-EU/EEA students on English-taught Bachelor’s and Master’s programmes. Scholarships can reduce or, in some cases, cover the fee.\", \"q\": \"Is education in Finland free for Indian students?\"}, {\"a\": \"At least €800 per month, equivalent to €9,600 for a one-year permit, held in the applicant’s own account, along with evidence of tuition payment or funds to cover it.\", \"q\": \"How much money must I show for the residence permit?\"}, {\"a\": \"Yes. A student permit allows work in any field for an average of 30 hours per week.\", \"q\": \"Can I work while studying?\"}, {\"a\": \"Yes. Graduates can apply for a permit of up to two years to look for work or start a business, and may switch to a work-based permit once employed.\", \"q\": \"Can I stay in Finland after graduating?\"}, {\"a\": \"Processing commonly takes one to three months from the identity-verification appointment, so apply as early as possible.\", \"q\": \"How long does the residence permit take?\"}, {\"a\": \"A valid passport, offer of admission, proof of funds and tuition, health insurance, academic certificates and transcripts, biometrics, and the application fee.\", \"q\": \"Which documents are needed?\"}, {\"a\": \"Not to study in an English-taught programme. Learning Finnish or Swedish, however, greatly improves part-time and graduate job prospects and day-to-day integration.\", \"q\": \"Do I need to learn Finnish?\"}, {\"a\": \"Family members may apply for residence permits based on family ties, subject to the income requirement and other conditions. Please speak to a counsellor about your circumstances.\", \"q\": \"Can my family join me?\"}, {\"a\": \"Winters are cold and snowy, with temperatures commonly several degrees below freezing, while summers are mild and bright, with long daylight hours and average highs around 20°C.\", \"q\": \"What is the weather like?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"Help & clarity\"}, {\"ctas\": [{\"label\": \"APPLY NOW — FREE COUNSELLING\", \"action\": \"counselling\"}], \"note\": \"Note: Fees, funds thresholds, and immigration rules are revised periodically. Figures are indicative and should be verified with the Finnish Immigration Service (migri.fi) and the chosen institution before applying.\", \"text\": \"Speak to one of our expert counsellors for a personalised assessment of your profile, university shortlist, scholarship options and visa strategy. Consultation is complimentary.\", \"type\": \"cta\", \"title\": \"Your Finnish chapter begins here\"}]',NULL,NULL,5,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (7,'study-in-italy','country',3,'Study in Italy','Italy','Study at Italy’s distinguished universities, from the world’s oldest seat of learning in Bologna to the design and engineering vanguard of Milan, with…','[{\"ctas\": [{\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}, {\"label\": \"Book Consultation\", \"action\": \"counselling\"}], \"lead\": \"Study at Italy’s distinguished universities, from the world’s oldest seat of learning in Bologna to the design and engineering vanguard of Milan, with EUROPA FUSION guiding every step.\", \"type\": \"hero\", \"title\": \"Where Eight Centuries of Scholarship Meet Your Ambition\", \"eyebrow\": \"Study in Italy\", \"highlight\": \"Your Ambition\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Oldest continuously operating university\", \"label\": \"University of Bologna\", \"value\": \"1088\"}, {\"sub\": \"Across top ranked Italian universities\", \"label\": \"English-taught degrees\", \"value\": \"300+\"}, {\"sub\": \"Each home to renowned universities\", \"label\": \"Italian regions\", \"value\": \"20\"}, {\"sub\": \"Bachelor’s + Master’s under Bologna Process\", \"label\": \"Years to degree\", \"value\": \"3 + 2\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Italy is the birthplace of the university itself. Its oldest institutions have shaped law, medicine, science and the arts for a millennium, matched today by world-class modern research and low living costs.\", \"items\": [{\"desc\": \"Degrees are recognised across Europe and globally under the Bologna Process, supporting mobility for further study and careers.\", \"icon\": \"globe-europe-africa\", \"title\": \"Internationally recognised qualifications\"}, {\"desc\": \"Italy is a global reference point for architecture, design, fashion, mechanical engineering, economics, physics and the humanities.\", \"icon\": \"globe-europe-africa\", \"title\": \"Distinctive academic strengths\"}, {\"desc\": \"Tuition at public universities is calculated according to family income, with regional DSU scholarships offering full fee waivers and living grants.\", \"icon\": \"piggy-bank\", \"title\": \"Exceptional value & regional grants\"}, {\"desc\": \"From the Renaissance cities of Florence, Bologna and Padua to the metropolitan energy of Milan and Rome, every campus offers a rich heritage.\", \"icon\": \"bank\", \"title\": \"A setting like no other\"}], \"style\": \"icon\", \"title\": \"An Education Rooted in History, Shaped for the Future\", \"columns\": 3, \"eyebrow\": \"Why Italy\"}, {\"type\": \"chronology\", \"intro\": \"Timeline of university foundation across Italy\", \"items\": [{\"name\": \"University of Bologna\", \"year\": 1088}, {\"name\": \"University of Padua\", \"year\": 1222}, {\"name\": \"Sapienza University of Rome\", \"year\": 1303}, {\"name\": \"University of Florence\", \"year\": 1321}, {\"name\": \"University of Pisa\", \"year\": 1343}, {\"name\": \"University of Turin\", \"year\": 1404}, {\"name\": \"Politecnico di Milano\", \"year\": 1863}, {\"name\": \"Ca\' Foscari University of Venice\", \"year\": 1868}, {\"name\": \"Bocconi University\", \"year\": 1902}], \"scale\": [1000, 1200, 1400, 1600, 1800, 2000], \"title\": \"Nine centuries of scholarship\"}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"The following institutions represent key destinations available to EUROPA FUSION students.\", \"items\": [{\"city\": \"Bologna\", \"desc\": \"Widely regarded as the oldest university in the world. Distinguished in law, humanities, engineering and the sciences.\", \"name\": \"University of Bologna\", \"type\": \"Founded 1088\"}, {\"city\": \"Padua\", \"desc\": \"The historic institution where Galileo once held a chair. Renowned for medicine, physics, psychology and engineering.\", \"name\": \"University of Padua\", \"type\": \"Founded 1222\"}, {\"city\": \"Rome\", \"desc\": \"One of Europe’s largest research universities, with an exceptionally broad range of disciplines and global ranking.\", \"name\": \"Sapienza University of Rome\", \"type\": \"Founded 1303\"}, {\"city\": \"Pisa\", \"desc\": \"A long tradition of excellence in computer science, engineering, mathematics, physics and natural sciences.\", \"name\": \"University of Pisa\", \"type\": \"Founded 1343\"}, {\"city\": \"Milan\", \"desc\": \"Italy’s leading technical university, internationally ranked top 20 globally for engineering, architecture and design.\", \"name\": \"Politecnico di Milano\", \"type\": \"Founded 1863\"}, {\"city\": \"Venice\", \"desc\": \"Established as a school of commerce; today strong in economics, international relations, languages and environmental sciences.\", \"name\": \"Ca’ Foscari University of Venice\", \"type\": \"Founded 1868\"}, {\"city\": \"Milan\", \"desc\": \"A premier European private institution of international standing in economics, finance, management and business law.\", \"name\": \"Bocconi University\", \"type\": \"Founded 1902\"}, {\"city\": \"Turin\", \"desc\": \"A comprehensive research university with strong links to automotive industry, management and medicine in Piedmont.\", \"name\": \"University of Turin\", \"type\": \"Founded 1404\"}], \"title\": \"Distinguished Institutions in Italy\", \"eyebrow\": \"Featured universities\"}, {\"id\": \"programmes\", \"rows\": [[\"Laurea (Bachelor’s)\", \"3 years\", \"180 CFU\", \"Entry on recognised 12-year secondary qualification; select English-taught programmes available.\"], [\"Laurea Magistrale (Master’s)\", \"2 years\", \"120 CFU\", \"The largest range of English-taught programmes; requires a relevant undergraduate Bachelor’s degree.\"], [\"Single-cycle Magistrale\", \"5–6 years\", \"300–360 CFU\", \"Medicine (IMAT exam), Dentistry, Pharmacy, Law and Architecture; direct integrated professional degrees.\"], [\"Master Universitario (1st/2nd)\", \"1–2 years\", \"60–120 CFU\", \"Professional career specialisation for graduates, frequently with industrial placements.\"], [\"Dottorato di Ricerca (PhD)\", \"3 years\", \"—\", \"Competitive research entry; most doctoral candidates receive fully funded fellowships.\"], [\"ITS Academy\", \"2 years\", \"—\", \"Higher vocational technical education linked directly to Italian manufacturing and design employers.\"]], \"type\": \"table\", \"chips\": [\"Engineering & Automotive Technology\", \"Architecture & Urban Design\", \"Business, Economics & Finance\", \"Medicine & Life Sciences (IMAT)\", \"Fashion & Luxury Brand Management\", \"Arts, Heritage & Humanities\", \"Data Science & Artificial Intelligence\", \"Political Science & International Relations\"], \"intro\": \"Italian higher education follows the Bologna model with Laurea, Laurea Magistrale, and direct single-cycle medical degrees.\", \"title\": \"Programmes and Qualifications in Italy\", \"columns\": [\"Qualification\", \"Duration\", \"Credits (CFU)\", \"Notes & Focus\"], \"eyebrow\": \"Academic pathways\", \"chips_title\": \"Popular fields of study in Italy\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 4000, \"min\": 1000, \"label\": \"Public university tuition (per year)\", \"value\": \"≈ €1,000 - €4,000\"}, {\"max\": 20000, \"min\": 6000, \"label\": \"Private university tuition (per year)\", \"value\": \"€6,000 - €20,000\"}, {\"max\": 14400, \"min\": 8400, \"label\": \"Living costs (per year)\", \"value\": \"€8,400 - €14,400\"}], \"type\": \"costs\", \"cards\": [{\"desc\": \"Need- and merit-based regional awards covering 100% tuition, free university accommodation and meal passes.\", \"title\": \"Regional DSU Scholarships\"}, {\"desc\": \"Competitive grants offered to international students through Italy’s diplomatic and consular channels.\", \"title\": \"Italian Government (MAECI)\"}, {\"desc\": \"Fee waivers and merit bursaries awarded directly by individual Italian universities (e.g. Politecnico di Milano, Bologna).\", \"title\": \"University Merit Awards\"}], \"intro\": \"A clear view of costs allows you to plan with confidence. Indicative annual ranges in euros:\", \"title\": \"Understanding the Investment in Italy\", \"eyebrow\": \"Fees & funding\", \"scale_max\": 25000, \"cards_title\": \"Scholarships & funding\", \"chart_title\": \"Indicative annual investment (varies by university, city and programme)\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"EUROPA FUSION offers a structured, transparent process so that each stage is handled with care and precision.\", \"items\": [{\"desc\": \"Academic record, career goals, budget, and preferred city are reviewed to define a realistic shortlist.\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Courses are matched to your profile, with attention to language of instruction, entry tests and deadlines.\", \"title\": \"Programme & university selection\"}, {\"desc\": \"Transcripts, degree certificates, English proof, CV, motivation letter and passport prepared and submitted on Universitaly.\", \"title\": \"Documents & Universitaly pre-enrolment\"}, {\"desc\": \"Where required, preparation for tests such as TOLC, IMAT (medicine), GMAT or GRE.\", \"title\": \"Entrance assessment\"}, {\"desc\": \"Acceptance confirmed; qualifications verified via CIMEA Statements of Comparability/Verification or Declaration of Value (DoV).\", \"title\": \"Offer & credential recognition\"}, {\"desc\": \"Consulate appointment booking, file review, accommodation and financial evidence according to official Italian requirements.\", \"title\": \"Student visa (Type D)\"}, {\"desc\": \"Permesso di Soggiorno (residence permit) application, Codice Fiscale, bank setup and university matriculation.\", \"title\": \"Arrival & settling in\"}], \"title\": \"From Enquiry to Enrolment\", \"eyebrow\": \"Your admission journey\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Common questions about studying and settling in Italy.\", \"items\": [{\"a\": \"Yes. Italian universities offer hundreds of English-taught programmes, particularly at Master’s level and in fields such as engineering, business, economics, design and medicine (via IMAT). The language of instruction should be verified for each course.\", \"q\": \"Can I study in Italy entirely in English?\"}, {\"a\": \"It is not required for English-taught programmes, but basic Italian greatly enriches daily life and improves your prospects of finding part-time work and internships. Many universities provide free Italian language classes.\", \"q\": \"Do I need to speak Italian?\"}, {\"a\": \"Italy is regarded as one of Europe’s most affordable destinations. Public university tuition is generally modest (€1,000–€4,000/yr) and is calculated according to family income (ISEE-Parificato). Living costs commonly range between €700 and €1,200 per month.\", \"q\": \"How much does it cost to study in Italy?\"}, {\"a\": \"The main intake begins in September or October, with a smaller intake in February or March at some universities. Application windows open early (between November and April), so preparing 9 to 12 months in advance is recommended.\", \"q\": \"When are the intakes and deadlines?\"}, {\"a\": \"Most English-taught programmes request evidence of proficiency, such as IELTS (normally 6.0–6.5) or TOEFL. A small number of universities accept a Medium of Instruction (MOI) certificate.\", \"q\": \"Is an English-language test mandatory?\"}, {\"a\": \"Yes! Regional DSU scholarships (such as DSU Toscana, EDISU Piemonte, ER.GO, Disco Lazio) provide full tuition waivers plus free accommodation, meals and up to €6,000–€7,000/yr in cash stipends based on family income. Italian Government MAECI scholarships are also available.\", \"q\": \"Are scholarships available to international students?\"}, {\"a\": \"Holders of an Italian student residence permit are permitted to work part-time up to 20 hours per week, up to a legal maximum of 1,040 hours per year.\", \"q\": \"Can I work while studying in Italy?\"}, {\"a\": \"Eligible Master’s and PhD graduates may apply for a 1-year Permesso di Soggiorno per Ricerca Lavoro (job-search permit) to find professional employment or register as a freelancer.\", \"q\": \"Can I remain in Italy after graduating?\"}, {\"a\": \"Typically: passport, academic transcripts, degree certificate, English certificate, CV, motivation letter, CIMEA certificate or Declaration of Value (DoV), and proof of financial means.\", \"q\": \"What documents will I need?\"}, {\"a\": \"We assist with university selection, CIMEA recognition, Universitaly portal pre-enrolment, DSU scholarship application, Italian student visa file assembly, and housing guidance.\", \"q\": \"How does EUROPA FUSION support my application?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"FAQ\"}, {\"ctas\": [{\"label\": \"Book Free Consultation\", \"action\": \"counselling\"}, {\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}], \"text\": \"Speak with a EUROPA FUSION counsellor for a personalised university shortlist and a clear roadmap to your offer letter.\", \"type\": \"cta\", \"title\": \"Begin Your Italian Chapter\"}]',NULL,NULL,6,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (8,'study-in-latvia','country',8,'Study in Latvia','Latvia','Earn an internationally recognised European degree in Riga and beyond, with EUROPA FUSION guiding every step of your journey.','[{\"ctas\": [{\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}, {\"label\": \"Book Consultation\", \"action\": \"counselling\"}], \"lead\": \"Earn an internationally recognised European degree in Riga and beyond, with EUROPA FUSION guiding every step of your journey.\", \"type\": \"hero\", \"title\": \"Where Baltic Innovation Meets Academic Value\", \"eyebrow\": \"Study in Latvia\", \"highlight\": \"Academic Value\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Among the lowest in the euro area\", \"label\": \"Monthly living costs\", \"value\": \"€450–700\"}, {\"sub\": \"Full-time work permitted during holidays\", \"label\": \"Weekly work allowed\", \"value\": \"20 hrs\"}, {\"sub\": \"In Latvia’s international student community\", \"label\": \"Nationalities represented\", \"value\": \"60+\"}, {\"sub\": \"Uses the euro, convenient European travel\", \"label\": \"EU & Schengen Area\", \"value\": \"EU\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Latvia offers international students a distinctive combination of recognised European qualifications, modern teaching and an exceptionally accessible cost of study.\", \"items\": [{\"desc\": \"Degrees follow the European Higher Education Area framework, supporting smooth recognition and mobility across Europe.\", \"icon\": \"patch-check\", \"title\": \"Europe-wide recognition\"}, {\"desc\": \"Tuition and living costs are among the most reasonable in the euro area, enabling students to invest confidently in their education.\", \"icon\": \"piggy-bank\", \"title\": \"Exceptional affordability\"}, {\"desc\": \"Latvia is particularly respected for medicine and health sciences, engineering, information technology, business, aviation and sciences.\", \"icon\": \"cpu\", \"title\": \"Strong academic fields\"}, {\"desc\": \"As a member of the EU and Schengen Area, Latvia places all of Europe within easy reach for study, travel and work.\", \"icon\": \"globe-europe-africa\", \"title\": \"A European gateway\"}, {\"desc\": \"Riga is a compact, creative and digitally connected capital with an international student community, while regional cities offer a peaceful pace.\", \"icon\": \"globe-europe-africa\", \"title\": \"A vibrant student environment\"}], \"style\": \"icon\", \"title\": \"A Modern European Education at Remarkable Value\", \"columns\": 3, \"eyebrow\": \"Why Latvia\"}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"The following institutions represent key destinations available to EUROPA FUSION students.\", \"items\": [{\"city\": \"Riga\", \"desc\": \"The country’s leading comprehensive university, with broad strengths in the humanities, social sciences, natural sciences and law.\", \"name\": \"University of Latvia\", \"type\": \"Public University\"}, {\"city\": \"Riga\", \"desc\": \"A principal centre for engineering, information technology, architecture and applied sciences, with a strong international profile.\", \"name\": \"Riga Technical University\", \"type\": \"Technical University\"}, {\"city\": \"Riga\", \"desc\": \"Internationally recognised for English-taught medicine, dentistry, pharmacy, nursing and health sciences programmes.\", \"name\": \"Rīga Stradiņš University\", \"type\": \"Medical & Health University\"}, {\"city\": \"Jelgava\", \"desc\": \"Specialising in agriculture, veterinary medicine, food technology, forestry, environmental sciences and engineering.\", \"name\": \"Latvia University of Life Sciences and Technologies\", \"type\": \"Public University\"}, {\"city\": \"Riga\", \"desc\": \"A business-focused institution offering English-taught programmes in management, finance, cybersecurity and entrepreneurship.\", \"name\": \"BA School of Business and Finance\", \"type\": \"Business School\"}, {\"city\": \"Riga\", \"desc\": \"An internationally oriented premier business school offering respected Bachelor’s and executive education in economics and management.\", \"name\": \"Stockholm School of Economics in Riga\", \"type\": \"Business School\"}, {\"city\": \"Riga\", \"desc\": \"Combines business, creative industries, architecture, audiovisual media and information technology with a practice-oriented approach.\", \"name\": \"RISEBA University of Applied Sciences\", \"type\": \"Private University\"}, {\"city\": \"Riga\", \"desc\": \"Focused on business administration, tourism, hospitality management, law and communication, with close links to industry.\", \"name\": \"Turiba University\", \"type\": \"Private University\"}], \"title\": \"Distinguished Institutions in Latvia\", \"eyebrow\": \"Featured universities\"}, {\"id\": \"programmes\", \"rows\": [[\"Bachelor’s degree\", \"3–4 years\", \"180–240\", \"Direct university admission; wide selection of English-taught programmes in business, IT, engineering and social sciences.\"], [\"Professional Bachelor’s\", \"4 years\", \"240\", \"Applied, career-oriented degree combining academic theory with practical industrial placements.\"], [\"Master’s degree\", \"1–2 years\", \"60–120\", \"English-taught options across management, engineering, data science and health; requires relevant Bachelor’s.\"], [\"Medicine, Dentistry & Pharmacy\", \"5–6 years\", \"300–360\", \"Internationally popular English-taught programmes; entry typically requires biology and chemistry preparation.\"], [\"Doctoral studies (PhD)\", \"3–4 years\", \"—\", \"Research-focused study within university doctoral schools with state research funding options.\"], [\"College (short-cycle)\", \"2–3 years\", \"120–180\", \"First-level professional higher education, usually leading to employment or Bachelor’s progression.\"]], \"type\": \"table\", \"chips\": [\"Medicine and Dentistry\", \"Engineering and Technology\", \"Information Technology and Data Science\", \"Business, Management and Finance\", \"Pharmacy and Health Sciences\", \"Tourism and Hospitality\", \"Design and Creative Industries\", \"Law and Social Sciences\"], \"intro\": \"Latvian higher education offers flexible degree pathways from college credentials to doctoral degrees.\", \"title\": \"Programmes and Qualifications in Latvia\", \"columns\": [\"Qualification\", \"Duration\", \"Credits (ECTS)\", \"Notes & Focus\"], \"eyebrow\": \"Academic pathways\", \"chips_title\": \"Popular fields of study in Latvia\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 6000, \"min\": 2500, \"label\": \"Tuition, non-medical programmes (per year)\", \"value\": \"≈ €2,500 - €6,000\"}, {\"max\": 15000, \"min\": 10000, \"label\": \"Tuition, medicine and dentistry (per year)\", \"value\": \"≈ €10,000 - €15,000\"}, {\"max\": 8400, \"min\": 5400, \"label\": \"Living costs (per year)\", \"value\": \"≈ €5,400 - €8,400\"}, {\"max\": 5000, \"min\": 3000, \"label\": \"Typical visa funds benchmark (per year)\", \"value\": \"≈ €3,000 - €5,000\"}], \"type\": \"costs\", \"cards\": [{\"desc\": \"Scholarships offered to international students under bilateral intergovernmental agreements and national programmes.\", \"title\": \"State Scholarships\"}, {\"desc\": \"EU-funded mobility and joint-degree opportunities for eligible students.\", \"title\": \"Erasmus+ & Mundus\"}, {\"desc\": \"Merit-based tuition reductions and academic awards offered directly by individual universities.\", \"title\": \"University Merit Awards\"}], \"intro\": \"A clear view of costs allows you to plan with confidence. Indicative annual ranges in euros:\", \"title\": \"Understanding the Investment in Latvia\", \"eyebrow\": \"Fees & funding\", \"scale_max\": 17500, \"cards_title\": \"Scholarships & funding\", \"chart_title\": \"Indicative annual investment in Latvia\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"EUROPA FUSION offers a structured, transparent process so that each stage is handled with care and precision.\", \"items\": [{\"desc\": \"Academic record, career goals, budget and preferred programme are reviewed to define a realistic shortlist.\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Courses are matched to your profile, with attention to language of instruction, entry requirements and deadlines.\", \"title\": \"Programme & university selection\"}, {\"desc\": \"Transcripts, certificates, language proof, CV, motivation letter and passport are prepared and submitted through the university’s application portal.\", \"title\": \"Online application\"}, {\"desc\": \"Where required, preparation for entrance tests or interviews, particularly for medicine, dentistry and health programmes.\", \"title\": \"Entrance assessment\"}, {\"desc\": \"Acceptance of your offer, issue of the official admission letter and payment of the first tuition instalment.\", \"title\": \"Admission & tuition confirmation\"}, {\"desc\": \"Preparation of the Type D visa file or direct residence permit application, including proof of funds and accommodation.\", \"title\": \"Visa or residence permit application\"}, {\"desc\": \"Registration of your address, residence permit formalities within the required period, accommodation and orientation.\", \"title\": \"Arrival & registration\"}], \"title\": \"From Enquiry to Enrolment\", \"eyebrow\": \"Your admission journey\"}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"cards\", \"intro\": \"We believe a student’s journey abroad should be guided with the same rigour as the education it leads to.\", \"items\": [{\"desc\": \"Personalised shortlisting and strategy from first enquiry to offer.\", \"icon\": \"compass\", \"title\": \"Admissions Counselling\"}, {\"desc\": \"Careful preparation of statements of purpose, CVs and supporting documents.\", \"icon\": \"file-earmark-text\", \"title\": \"Application Excellence\"}, {\"desc\": \"Support with State, Erasmus+ and university scholarship options.\", \"icon\": \"award\", \"title\": \"Scholarship Guidance\"}, {\"desc\": \"Structured assistance with visa documentation, AIC verification, and financial evidence.\", \"icon\": \"passport\", \"title\": \"Visa & Residence Permit\"}, {\"desc\": \"Guidance on university dormitories and private student housing in Riga.\", \"icon\": \"house-door\", \"title\": \"Accommodation Support\"}, {\"desc\": \"Briefings before you fly and continued support after you arrive in Latvia.\", \"icon\": \"airplane\", \"title\": \"Pre-Departure & Beyond\"}], \"style\": \"icon\", \"title\": \"Your Partner for the Journey\", \"columns\": 3, \"eyebrow\": \"Why EUROPA FUSION\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Common questions about studying and settling in Latvia.\", \"items\": [{\"a\": \"Yes. Latvian universities offer a wide choice of English-taught programmes at Bachelor’s, Master’s and doctoral level, including medicine, dentistry, engineering, business and information technology.\", \"q\": \"Can I study in Latvia entirely in English?\"}, {\"a\": \"It is not required for English-taught programmes, though learning basic Latvian or Russian is helpful for daily life and part-time work. Universities typically offer introductory language courses.\", \"q\": \"Do I need to speak Latvian?\"}, {\"a\": \"Latvia is one of Europe’s most affordable study destinations. Tuition for non-medical programmes is commonly in the range of €2,500 to €6,000 per year, while medicine and dentistry cost €10,000 to €15,000. Monthly living costs typically range from €450 to €700.\", \"q\": \"How much does it cost to study in Latvia?\"}, {\"a\": \"The main intake begins in September, with a smaller intake in February at some institutions. Medicine and health programmes often close applications earlier in the year (April–June), so early application is advisable.\", \"q\": \"When are the intakes and deadlines?\"}, {\"a\": \"Many programmes assess applicants on academic record and a motivation letter. Medicine and health programmes usually require evidence of biology and chemistry preparation and an online entrance test or interview.\", \"q\": \"Do I need to take an entrance examination?\"}, {\"a\": \"Universities usually accept IELTS (5.5–6.5), TOEFL or an equivalent, and some conduct their own interview or test.\", \"q\": \"Which English-language tests are accepted?\"}, {\"a\": \"Applicants must demonstrate sufficient funds for their stay. In practice, proof of around €3,000 to €5,000 for the first year is commonly expected, often alongside payment of the first tuition instalment.\", \"q\": \"How much money must I show for the visa and residence permit?\"}, {\"a\": \"Non-EU students holding a residence permit for study may generally work up to 20 hours per week during term and full-time during official summer holidays.\", \"q\": \"Can I work while studying in Latvia?\"}, {\"a\": \"Graduates may apply for a temporary residence permit to seek employment or start a business, and may then transition to a long-term work-based permit.\", \"q\": \"Can I remain in Latvia after graduating?\"}, {\"a\": \"Yes. Options include Latvian State scholarships under bilateral agreements, Erasmus+ opportunities and merit-based tuition fee reductions from individual universities.\", \"q\": \"Are scholarships available for international students?\"}, {\"a\": \"Students may choose university residences (€100–€200/month), which are usually the most economical option, or private rental apartments in Riga (€250–€450/month).\", \"q\": \"What are accommodation options?\"}, {\"a\": \"Typically: passport, academic transcripts and certificates (with apostille/AIC recognition), language-test results, CV, motivation letter, proof of financial means, proof of accommodation and health insurance.\", \"q\": \"What documents will I need?\"}, {\"a\": \"We assist at every stage: profile assessment, university selection, AIC document verification, application prep, entrance coaching, visa support, accommodation and pre-departure briefing.\", \"q\": \"How does EUROPA FUSION support my application?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"FAQ\"}, {\"ctas\": [{\"label\": \"Book Free Consultation\", \"action\": \"counselling\"}, {\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}], \"text\": \"Speak with a EUROPA FUSION counsellor for a personalised university shortlist and a clear roadmap to your offer letter.\", \"type\": \"cta\", \"title\": \"Begin Your Latvian Chapter\"}]',NULL,NULL,7,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (9,'study-in-lithuania','country',9,'Study in Lithuania','Lithuania','Earn a respected European degree in Vilnius, Kaunas and beyond, with EUROPA FUSION guiding every step of your journey.','[{\"ctas\": [{\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}, {\"label\": \"Book Consultation\", \"action\": \"counselling\"}], \"lead\": \"Earn a respected European degree in Vilnius, Kaunas and beyond, with EUROPA FUSION guiding every step of your journey.\", \"type\": \"hero\", \"title\": \"Where Baltic Excellence Meets Digital Ambition\", \"eyebrow\": \"Study in Lithuania\", \"highlight\": \"Digital Ambition\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Most accessible in the euro area\", \"label\": \"Monthly living costs\", \"value\": \"€500–800\"}, {\"sub\": \"With student residence permit\", \"label\": \"Weekly work permitted\", \"value\": \"40 hrs\"}, {\"sub\": \"Across top universities & UAS\", \"label\": \"English-taught programmes\", \"value\": \"500+\"}, {\"sub\": \"Stay back to seek work\", \"label\": \"Post-study residence permit\", \"value\": \"1 year\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Lithuania offers international students a compelling combination of recognised European qualifications, modern teaching and a remarkably accessible cost of study set within a safe, digitally advanced Baltic environment.\", \"items\": [{\"desc\": \"Degrees follow the European Higher Education Area framework, supporting smooth recognition and mobility across Europe.\", \"icon\": \"patch-check\", \"title\": \"Europe-wide recognition\"}, {\"desc\": \"Tuition and living costs are among the most reasonable in the euro area, allowing students to invest in their education with confidence.\", \"icon\": \"piggy-bank\", \"title\": \"Exceptional affordability\"}, {\"desc\": \"Lithuania is distinguished in information technology, fintech, life sciences, engineering, business, and health sciences.\", \"icon\": \"cpu\", \"title\": \"Innovation-driven strengths\"}, {\"desc\": \"Students holding a residence permit may work up to 40 hours alongside studies, and eligible graduates can remain to seek employment.\", \"icon\": \"briefcase\", \"title\": \"Practical career pathways\"}, {\"desc\": \"As a member of the EU and Schengen Area, Lithuania places all of Europe within easy reach for study, travel, and international careers.\", \"icon\": \"globe-europe-africa\", \"title\": \"A European gateway\"}], \"style\": \"icon\", \"title\": \"A Forward-Looking European Education at Exceptional Value\", \"columns\": 3, \"eyebrow\": \"Why Lithuania\"}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"The following institutions represent key destinations available to EUROPA FUSION students.\", \"items\": [{\"city\": \"Vilnius\", \"desc\": \"Lithuania’s leading comprehensive research university, distinguished in humanities, law, natural sciences, medicine and social sciences.\", \"name\": \"Vilnius University\", \"type\": \"Public University\"}, {\"city\": \"Kaunas\", \"desc\": \"A major Baltic centre for engineering, information technology, design and business, with a strongly international student body.\", \"name\": \"Kaunas University of Technology\", \"type\": \"Technical University\"}, {\"city\": \"Vilnius\", \"desc\": \"Known for engineering, architecture, construction, transport and technology, with close ties to European industry.\", \"name\": \"Vilnius Gediminas Technical University\", \"type\": \"Technical University\"}, {\"city\": \"Kaunas\", \"desc\": \"A liberal-arts-oriented university recognised for social sciences, humanities, informatics, arts and education.\", \"name\": \"Vytautas Magnus University\", \"type\": \"Public University\"}, {\"city\": \"Kaunas\", \"desc\": \"A specialist institution offering English-taught programmes in medicine, dentistry, pharmacy, veterinary and health sciences.\", \"name\": \"Lithuanian University of Health Sciences\", \"type\": \"Medical University\"}, {\"city\": \"Vilnius & Kaunas\", \"desc\": \"An internationally oriented institution focused on business, economics, data management, finance and entrepreneurship.\", \"name\": \"ISM University of Management and Economics\", \"type\": \"Business University\"}, {\"city\": \"Vilnius\", \"desc\": \"Specialising in law, public governance, security, cybersecurity, social sciences and international communication.\", \"name\": \"Mykolas Romeris University\", \"type\": \"Public University\"}, {\"city\": \"Vilnius\", \"desc\": \"A practice-oriented institution offering career-focused programmes in business, technology, healthcare and creative fields.\", \"name\": \"Vilnius University of Applied Sciences\", \"type\": \"Applied Sciences\"}], \"title\": \"Distinguished Institutions in Lithuania\", \"eyebrow\": \"Featured universities\"}, {\"id\": \"programmes\", \"rows\": [[\"Bachelor’s degree\", \"3.5–4 years\", \"210–240\", \"Direct university admission; wide selection of English-taught courses in business, IT, engineering and social sciences.\"], [\"Professional Bachelor’s (UAS)\", \"3–3.5 years\", \"180–210\", \"Practice-oriented degree delivered by colleges and universities of applied sciences, including paid company placements.\"], [\"Master’s degree\", \"1.5–2 years\", \"90–120\", \"English-taught options across management, tech, data science and health; requires a relevant Bachelor’s degree.\"], [\"Integrated programmes\", \"5–6 years\", \"300–360\", \"Medicine, Dentistry, Pharmacy and Law; direct path from high school to professional practice.\"], [\"Doctoral studies (PhD)\", \"4 years\", \"—\", \"Research-focused study within university doctoral schools, often with state-funded stipends.\"], [\"Foundation & preparatory\", \"Up to 1 year\", \"—\", \"Optional English language and scientific subject preparation offered by selected institutions.\"]], \"type\": \"table\", \"chips\": [\"Medicine & Dentistry\", \"Engineering & Technology\", \"Information Technology & Data Science\", \"Business, Management & FinTech\", \"Law & Public Governance\", \"Pharmacy & Health Sciences\", \"Design & Creative Industries\", \"Social Sciences & Humanities\"], \"intro\": \"Lithuanian higher education follows the European three-cycle model giving a portable route from undergraduate to doctoral study.\", \"title\": \"Programmes and Qualifications\", \"columns\": [\"Qualification\", \"Duration\", \"Credits (ECTS)\", \"Notes & Focus\"], \"eyebrow\": \"Academic pathways\", \"chips_title\": \"Popular fields of study in Lithuania\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 6000, \"min\": 1500, \"label\": \"Tuition, non-medical programmes (per year)\", \"value\": \"≈ €1,500 - €6,000\"}, {\"max\": 14000, \"min\": 10000, \"label\": \"Tuition, medicine and dentistry (per year)\", \"value\": \"≈ €10,000 - €14,000\"}, {\"max\": 9600, \"min\": 6000, \"label\": \"Living costs (per year)\", \"value\": \"≈ €6,000 - €9,600\"}, {\"max\": 7500, \"min\": 7500, \"label\": \"Typical visa funds benchmark (per year)\", \"value\": \"≈ €7,500\"}], \"type\": \"costs\", \"cards\": [{\"desc\": \"Offered to international students through Lithuanian national education exchanges and bilateral agreements.\", \"title\": \"National Scholarships\"}, {\"desc\": \"EU-funded mobility and semester exchange grants across Schengen partner universities.\", \"title\": \"Erasmus+ & Mobility\"}, {\"desc\": \"Full or partial tuition fee reductions and performance stipends directly from individual universities.\", \"title\": \"University Merit Awards\"}], \"intro\": \"A clear view of costs allows you to plan with confidence. Indicative annual ranges in euros:\", \"title\": \"Understanding the Investment in Lithuania\", \"eyebrow\": \"Fees & funding\", \"scale_max\": 17500, \"cards_title\": \"Scholarships & funding\", \"chart_title\": \"Indicative annual investment in Lithuania\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"EUROPA FUSION offers a structured, transparent process so that each stage is handled with care and precision.\", \"items\": [{\"desc\": \"Academic record, career goals, budget and preferred programme are reviewed to define a realistic shortlist.\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Courses are matched to your profile, with attention to language of instruction, entry requirements and deadlines.\", \"title\": \"Programme & university selection\"}, {\"desc\": \"Transcripts, certificates, language proof, CV, motivation letter and passport are prepared and submitted through the university portal.\", \"title\": \"Online application\"}, {\"desc\": \"Where required, structured preparation for entrance tests or interviews, particularly for medicine and health programmes.\", \"title\": \"Entrance assessment\"}, {\"desc\": \"Acceptance of your official offer within stated deadlines, followed by payment of the first-year tuition invoice.\", \"title\": \"Offer acceptance & tuition payment\"}, {\"desc\": \"Preparation of the temporary residence permit (TRP) or national D-visa file, including proof of funds, accommodation and health insurance.\", \"title\": \"Residence permit or visa application\"}, {\"desc\": \"Registration of your place of residence shortly after arrival, completion of permit formalities, accommodation and university orientation.\", \"title\": \"Arrival & registration\"}], \"title\": \"From Enquiry to Enrolment\", \"eyebrow\": \"Your admission journey\"}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"cards\", \"intro\": \"We believe a student’s journey abroad should be guided with the same rigour as the education it leads to.\", \"items\": [{\"desc\": \"Personalised shortlisting and strategy from first enquiry to offer.\", \"icon\": \"compass\", \"title\": \"Admissions Counselling\"}, {\"desc\": \"Careful preparation of statements of purpose, CVs and academic credentials.\", \"icon\": \"file-earmark-text\", \"title\": \"Application Excellence\"}, {\"desc\": \"Support with State, Erasmus+ and university merit awards.\", \"icon\": \"award\", \"title\": \"Scholarship Guidance\"}, {\"desc\": \"Structured assistance with Lithuanian migration requirements and proof of funds.\", \"icon\": \"passport\", \"title\": \"Visa & TRP Support\"}, {\"desc\": \"Guidance on university dormitories and private housing in Vilnius and Kaunas.\", \"icon\": \"house-door\", \"title\": \"Accommodation Support\"}, {\"desc\": \"Briefings before you fly and continued support after you arrive in Lithuania.\", \"icon\": \"airplane\", \"title\": \"Pre-Departure & Beyond\"}], \"style\": \"icon\", \"title\": \"Your Partner for the Journey\", \"columns\": 3, \"eyebrow\": \"Why EUROPA FUSION\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Common questions about studying and settling in Lithuania.\", \"items\": [{\"a\": \"Yes. Lithuanian universities and colleges offer more than 500 English-taught programmes at Bachelor’s, Master’s and doctoral level, including medicine, engineering, business, IT and the social sciences.\", \"q\": \"Can I study in Lithuania entirely in English?\"}, {\"a\": \"It is not required for English-taught programmes, though basic Lithuanian is helpful in daily life and when seeking part-time work. Universities commonly offer free or low-cost introductory language courses.\", \"q\": \"Do I need to speak Lithuanian?\"}, {\"a\": \"Lithuania is one of Europe’s most affordable study destinations. Tuition for English-taught programmes at public universities typically ranges from about €1,500 to €6,000 per year, while medicine and dentistry range from €10,000 to €14,000. Monthly living costs commonly range from €500 to €800.\", \"q\": \"How much does it cost to study in Lithuania?\"}, {\"a\": \"The main intake begins in September, with a smaller intake in February at some institutions. International application deadlines often fall between April and June, and non-EU applicants should apply early to allow time for permit processing.\", \"q\": \"When are the intakes and deadlines?\"}, {\"a\": \"Many programmes assess applicants on academic record, motivation letter and English proficiency. Medicine and certain health and creative programmes require entrance examinations or interviews.\", \"q\": \"Do I need to take an entrance examination?\"}, {\"a\": \"Universities usually accept IELTS (typically 5.5-6.5), TOEFL, or equivalent tests. Some institutions conduct their own online interview or internal assessment.\", \"q\": \"Which English-language tests are accepted?\"}, {\"a\": \"Applicants must demonstrate sufficient funds for their stay. Many universities and Lithuanian migration authorities expect proof of around €7,500 for the first year, often alongside payment of the first tuition invoice.\", \"q\": \"How much money must I show for the permit?\"}, {\"a\": \"Yes! Non-EU students holding a temporary residence permit for study in Lithuania may work up to 40 hours per week during their studies.\", \"q\": \"Can I work while studying in Lithuania?\"}, {\"a\": \"Eligible graduates of Lithuanian universities may apply for a temporary residence permit to seek employment or start a business, valid for up to 12 months, and then easily transition to an EU Blue Card or work permit.\", \"q\": \"Can I remain in Lithuania after graduating?\"}, {\"a\": \"Yes. Options include Lithuanian state scholarships, Erasmus+ mobility grants, and tuition fee waivers or merit discounts offered directly by individual universities.\", \"q\": \"Are scholarships available for international students?\"}, {\"a\": \"Most universities offer on-campus student dormitories (typically €100–€250/month), which are the most economical option, alongside shared private apartments in Vilnius and Kaunas (€250–€450/month).\", \"q\": \"What are accommodation options?\"}, {\"a\": \"We assist at every stage: profile assessment, university shortlisting, SOP & CV editing, document legalization/apostille guidance, entrance prep, visa file verification, accommodation search, and pre-departure briefings.\", \"q\": \"How does EUROPA FUSION support my application?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"FAQ\"}, {\"ctas\": [{\"label\": \"Book Free Consultation\", \"action\": \"counselling\"}, {\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}], \"text\": \"Speak with a EUROPA FUSION counsellor for a personalised university shortlist and a clear roadmap to your offer letter.\", \"type\": \"cta\", \"title\": \"Begin Your Lithuanian Chapter\"}]',NULL,NULL,8,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (10,'study-in-netherlands','country',6,'Study in the Netherlands','Netherlands','Research-led learning, English-taught degrees and a year to launch your career. Begin your Dutch degree with EUROPA FUSION.','[{\"ctas\": [{\"label\": \"Get Free Evaluation\", \"action\": \"evaluation\"}], \"type\": \"hero\", \"chips\": [\"EUROPA FUSION\", \"Abroad Education Consultants\"], \"title\": \"Dutch Design, Global Horizons\", \"eyebrow\": \"Study in the Netherlands\", \"tagline\": \"Research-led learning • English-taught degrees • A year to launch your career\", \"highlight\": \"Global Horizons\"}, {\"cta\": {\"label\": \"Get Free Evaluation\", \"action\": \"evaluation\"}, \"type\": \"intro\", \"title\": \"Dutch Design, Global Horizons: Your Degree in the Netherlands\", \"paragraphs\": [\"The Netherlands has long been a meeting-place of ideas: a small, maritime nation whose universities have shaped science, law, trade and design for four centuries. Today it combines that intellectual heritage with a modern, internationally minded education system, in which problem-based learning, small-group teaching and close ties with industry are the norm rather than the exception.\", \"Begin with a complimentary profile evaluation at EUROPA FUSION\"]}, {\"type\": \"stats\", \"items\": [{\"label\": \"Dutch universities in the QS World top 200 (2026)\", \"value\": \"8\"}, {\"label\": \"Orientation Year to search for work\", \"value\": \"12 mo\"}, {\"label\": \"Weekly work allowance during term-time\", \"value\": \"16 hrs\"}, {\"label\": \"IND monthly funds norm (2026, excl. tuition)\", \"value\": \"€1,131\"}]}, {\"id\": \"why\", \"note\": \"Each is a matter of substance rather than marketing. Dutch universities are publicly funded and externally accredited; teaching is interactive and expects independent thought; and the national habit of directness and equality tends to put international students at ease quickly.\", \"type\": \"cards\", \"intro\": \"Eight considerations explain why the Netherlands consistently ranks among the most sought-after destinations for Indian postgraduates and undergraduates alike.\", \"items\": [{\"desc\": \"Eight universities in the QS top 200\", \"title\": \"Ranked worldwide\"}, {\"desc\": \"A very wide range of degrees in English\", \"title\": \"English-taught\"}, {\"desc\": \"12-month Orientation Year after graduation\", \"title\": \"Career runway\"}, {\"desc\": \"Tech, logistics, agri-food, life sciences\", \"title\": \"Innovation economy\"}, {\"desc\": \"Safe, cycling-first, work-life balance\", \"title\": \"Quality of life\"}, {\"desc\": \"NL Scholarship and institutional awards\", \"title\": \"Funding\"}, {\"desc\": \"Schengen travel on your doorstep\", \"title\": \"Heart of Europe\"}, {\"desc\": \"Diverse, international, English-friendly\", \"title\": \"Open society\"}], \"style\": \"numbered\", \"title\": \"Why the Netherlands?\", \"columns\": 4, \"eyebrow\": \"Distinguishing advantages\"}, {\"type\": \"intro\", \"title\": \"How Dutch Higher Education Is Organised\", \"eyebrow\": \"Binary education system\", \"paragraphs\": [\"Dutch higher education is binary. Research universities (WO) emphasise academic theory and research; universities of applied sciences (HBO) emphasise professional practice and typically embed internships. Both award internationally recognised degrees, and a growing number of programmes at each level are taught entirely in English.\"]}, {\"note\": \"60 ECTS credits represent one full academic year of study.\", \"type\": \"split\", \"title\": \"Two routes through Dutch higher education\", \"columns\": [{\"badge\": \"WO\", \"title\": \"Research universities\", \"points\": [\"Bachelor’s: 3 years • BSc / BA theory and research\", \"Master’s: 1–2 years • MSc / MA specialisation\", \"PhD: 4 years • salaried research position\"]}, {\"badge\": \"HBO\", \"title\": \"Universities of applied sciences\", \"points\": [\"Bachelor’s: 4 years • professional practice and internships\", \"Master’s: 1–2 years • applied and professional focus\"]}]}, {\"text\": \"Teaching is organised in short blocks, with a strong emphasis on tutorials, group projects and continuous assessment. Because progress is monitored, with the university reporting study results to the immigration authority, applicants should choose a programme they can sustain, not merely the most prestigious one available.\", \"type\": \"notice\"}, {\"id\": \"universities\", \"note\": \"Applicants seeking a more vocational route should also consider the universities of applied sciences, such as Hanze, Fontys, Saxion and Inholland, which offer English-taught Bachelor’s degrees in business, engineering, information technology, hospitality, design and the creative industries.\", \"type\": \"universities\", \"intro\": \"The following research universities are among the most popular with international applicants. Rankings are drawn from the QS World University Rankings 2026 and are given for orientation only.\", \"items\": [{\"city\": \"Delft\", \"desc\": \"Engineering, architecture, applied sciences, computer science\", \"name\": \"Delft University of Technology\", \"rank\": \"#47\"}, {\"city\": \"Amsterdam\", \"desc\": \"Business, economics, law, social sciences, humanities\", \"name\": \"University of Amsterdam\", \"rank\": \"#53\"}, {\"city\": \"Utrecht\", \"desc\": \"Life sciences, geosciences, psychology, law\", \"name\": \"Utrecht University\", \"rank\": \"#103\"}, {\"city\": \"Leiden\", \"desc\": \"Law, international relations, humanities, biomedical sciences\", \"name\": \"Leiden University\", \"rank\": \"#119\"}, {\"city\": \"Rotterdam\", \"desc\": \"Management, economics, finance, health policy\", \"name\": \"Erasmus University Rotterdam\", \"rank\": \"#140\"}, {\"city\": \"Groningen\", \"desc\": \"Broad research university; strong in physics, arts and medicine\", \"name\": \"University of Groningen\", \"rank\": \"#147\"}, {\"city\": \"Wageningen\", \"desc\": \"Agri-food, environment and life sciences\", \"name\": \"Wageningen University & Research\", \"rank\": \"#153\"}, {\"city\": \"Amsterdam\", \"desc\": \"Sciences, business, humanities, interdisciplinary programmes\", \"name\": \"Vrije Universiteit Amsterdam\", \"rank\": \"#194\"}, {\"city\": \"Enschede\", \"desc\": \"Engineering, technology, entrepreneurship\", \"name\": \"University of Twente\", \"rank\": \"#203\"}, {\"city\": \"Maastricht\", \"desc\": \"Problem-based learning, business, European studies\", \"name\": \"Maastricht University\", \"rank\": \"#239\"}], \"title\": \"Leading Universities\", \"eyebrow\": \"Global rankings\"}, {\"id\": \"fields\", \"rows\": [[\"Engineering and technology\", \"Civil, mechanical, electrical and sustainable energy engineering; robotics; water management\"], [\"Computing and data\", \"Computer science, artificial intelligence, data science, cybersecurity, software engineering\"], [\"Business and finance\", \"International business, finance, marketing, supply-chain and logistics, analytics\"], [\"Life sciences and agriculture\", \"Biotechnology, biomedical sciences, food technology, environmental sciences\"], [\"Social sciences and law\", \"Psychology, sociology, international law, public policy, international relations\"], [\"Design and creative industries\", \"Architecture, game design, urban planning, media and communication\"]], \"type\": \"table\", \"title\": \"Fields of Study in Demand\", \"columns\": [\"Discipline\", \"Representative programmes\"], \"eyebrow\": \"Industry alignment\"}, {\"id\": \"admission\", \"rows\": [[\"Bachelor’s\", \"Secondary-school certificate recognised as equivalent to Dutch pre-university education; good grades (broadly a B average); motivation letter; references where requested\", \"Some programmes apply selection or a numerus fixus quota, with an earlier deadline of 15 January.\"], [\"Master’s\", \"A relevant Bachelor’s degree; a strong academic record (competitive courses often look for the equivalent of about 7.5 out of 10); CV, motivation letter and references\", \"Business and management courses may ask for GMAT or GRE scores; others may ask for a portfolio or writing sample.\"]], \"type\": \"table\", \"intro\": \"Entry standards are set by each programme, and competitive courses may require more than the minimum. In general:\", \"title\": \"Admission Requirements\", \"columns\": [\"Level\", \"Academic requirements\", \"Additional considerations\"], \"eyebrow\": \"Academic standards\"}, {\"type\": \"cards\", \"items\": [{\"desc\": \"English-taught programmes require evidence of proficiency. Typical thresholds are an <strong>IELTS Academic score of 6.0 to 7.0 overall</strong> or a <strong>TOEFL iBT score of 80 to 100</strong>, with higher scores for competitive programmes and minimum sub-scores in writing. Dutch is not required for English-taught degrees.\", \"icon\": \"translate\", \"title\": \"English-Language Proficiency\"}], \"style\": \"plain\", \"columns\": 2}, {\"id\": \"intakes\", \"note\": \"Admission calendar for a September start\", \"type\": \"timeline\", \"intro\": \"Most programmes begin in September, with a smaller number admitting students in February. Applicants from outside the EU/EEA are generally expected to apply earlier than EU applicants, to allow time for the residence permit; deadlines of 1 April to 1 May are common, although some institutions close earlier.\", \"items\": [{\"desc\": \"15 January: numerus fixus programmes\", \"label\": \"Jan\", \"title\": \"15 January\"}, {\"desc\": \"Studielink and university applications (non-EU: typically by 1 April–1 May)\", \"label\": \"Nov–May\", \"title\": \"Studielink and university applications\"}, {\"desc\": \"Scholarship applications (institutional deadlines vary, Feb–May)\", \"label\": \"Nov–May\", \"title\": \"Scholarship applications\"}, {\"desc\": \"Admission, fees, proof of funds\", \"label\": \"Apr–Jul\", \"title\": \"Admission, fees, proof of funds\"}, {\"desc\": \"Residence permit processing\", \"label\": \"May–Aug\", \"title\": \"Residence permit processing\"}, {\"desc\": \"Arrive and settle\", \"label\": \"Aug–Sep\", \"title\": \"Arrive and settle\"}], \"title\": \"Intakes and Deadlines\", \"eyebrow\": \"Timelines & deadlines\"}, {\"id\": \"process\", \"type\": \"steps\", \"intro\": \"Applications to Dutch universities are made through Studielink, the national platform, followed by each university’s own portal for supporting documents.\", \"items\": [{\"tag\": \"Programmes and universities\", \"desc\": \"Define your goals and shortlist programmes that fit your academic profile and career objectives.\", \"title\": \"Shortlist\"}, {\"tag\": \"Register and apply (up to four choices)\", \"desc\": \"Register on Studielink and submit your applications. You may apply for up to four programmes, with a lower limit for numerus fixus courses.\", \"title\": \"Studielink\"}, {\"tag\": \"Upload documents; sit any tests\", \"desc\": \"Complete the institution’s portal: transcripts, certificates, language scores, motivation letter, CV, and any entrance assessment.\", \"title\": \"Portal\"}, {\"tag\": \"Conditional or unconditional offer\", \"desc\": \"Receive a decision. An offer may be conditional on final results or test scores; keep certified copies of all documents.\", \"title\": \"Admission\"}, {\"tag\": \"Tuition and proof of means\", \"desc\": \"Confirm your place, pay any deposit or tuition fee, and assemble proof of the funds required for the permit.\", \"title\": \"Funds\"}, {\"tag\": \"University files MVV and VVR\", \"desc\": \"The university, as recognised sponsor, applies on your behalf for the entry visa (MVV) and residence permit (VVR).\", \"title\": \"Permit\"}, {\"tag\": \"Collect MVV, book flight, find a room\", \"desc\": \"Collect your MVV, arrange travel, secure accommodation and take out health insurance.\", \"title\": \"Travel\"}, {\"tag\": \"Collect VVR, register, BSN\", \"desc\": \"On arrival, collect your residence card, register with the municipality, obtain your citizen service number (BSN) and open a bank account.\", \"title\": \"Settle\"}], \"title\": \"From First Enquiry to Your First Lecture\", \"eyebrow\": \"Step-by-step process\"}, {\"id\": \"visa\", \"note\": \"<strong>Study progress matters:</strong> The permit is linked to your enrolment. Universities typically expect students to earn at least 50% of the credits for the academic year, and report outcomes directly to the IND. Planning a realistic workload, especially if you work part-time, protects your status.\", \"type\": \"cards\", \"intro\": \"Indian students require two permissions for a full degree. The <strong>MVV</strong> is the provisional entry visa, collected from the Dutch representation before travel; the <strong>VVR</strong> is the residence permit, collected in the Netherlands after arrival. Because the university files both, the applicant’s principal task is to document eligibility accurately.\", \"items\": [{\"desc\": \"An official offer of admission from a recognised Dutch sponsor institution.\", \"icon\": \"patch-check\", \"title\": \"Admission confirmation\"}, {\"desc\": \"The IND study norm for 2026 is €1,130.77 per month (excluding tuition), demonstrated in addition to the fee.\", \"icon\": \"cash-stack\", \"title\": \"Sufficient means (IND norm)\"}, {\"desc\": \"Valid for the intended period of study with adequate blank pages.\", \"icon\": \"passport\", \"title\": \"Valid passport\"}, {\"desc\": \"Adequate cover for the full stay; students who work require Dutch basic healthcare (Basisverzekering).\", \"icon\": \"heart-pulse\", \"title\": \"Health insurance\"}, {\"desc\": \"TB screening (where applicable) and civil documents such as legalised birth certificates.\", \"icon\": \"file-earmark-text\", \"title\": \"Screening and civil documents\"}], \"style\": \"icon\", \"title\": \"Visa and Residence Permit\", \"columns\": 3, \"eyebrow\": \"Immigration & entry\"}, {\"id\": \"tuition\", \"rows\": [[\"EU/EEA students (statutory fee)\", \"€2,694 (2026–27)\", \"Set nationally; identical across institutions\"], [\"Non-EU/EEA Bachelor’s\", \"From about €9,000 to €24,000\", \"Varies by institution and field\"], [\"Non-EU/EEA Master’s\", \"From about €10,000 to €30,000\", \"Higher for MBA and specialised programmes\"], [\"Doctoral candidates\", \"Generally no tuition\", \"Usually salaried as employees of the university\"]], \"type\": \"table\", \"intro\": \"Tuition Fees\", \"title\": \"The Cost of Studying\", \"columns\": [\"Category\", \"Annual fee\", \"Remarks\"], \"eyebrow\": \"Financial overview\"}, {\"id\": \"living\", \"rows\": [{\"max\": 900, \"min\": 400, \"label\": \"Accommodation\", \"value\": \"€400 – 900\"}, {\"max\": 350, \"min\": 200, \"label\": \"Food and groceries\", \"value\": \"€200 – 350\"}, {\"max\": 120, \"min\": 50, \"label\": \"Transport\", \"value\": \"€50 – 120\"}, {\"max\": 120, \"min\": 50, \"label\": \"Health insurance\", \"value\": \"€50 – 120\"}, {\"max\": 300, \"min\": 150, \"label\": \"Books and leisure\", \"value\": \"€150 – 300\"}, {\"max\": 1500, \"min\": 1000, \"label\": \"Typical total\", \"value\": \"€1,000 – 1,500\"}, {\"max\": 1131, \"min\": 1131, \"label\": \"IND 2026 study norm\", \"value\": \"€1,131\"}], \"type\": \"costs\", \"intro\": \"Housing is the principal variable. Amsterdam, Utrecht and Leiden are the most expensive cities; Groningen, Enschede, Tilburg and Wageningen are markedly cheaper.\", \"title\": \"Living Costs\", \"scale_max\": 1600, \"chart_title\": \"Indicative monthly living costs (€)\"}, {\"type\": \"cards\", \"items\": [{\"desc\": \"Student rooms and shared flats are in short supply, so apply as soon as you are admitted; most universities offer assistance.\", \"icon\": \"house-door\", \"title\": \"Housing\"}, {\"desc\": \"A bicycle (€40–150 second-hand) is the national student vehicle; public transport is efficient but costly without a discount.\", \"icon\": \"bicycle\", \"title\": \"Transport\"}, {\"desc\": \"Cooking at home keeps groceries to roughly €120–250/mo; eating out costs €8–16 per meal.\", \"icon\": \"cash-coin\", \"title\": \"Meals\"}], \"style\": \"plain\", \"columns\": 3}, {\"id\": \"scholarships\", \"note\": \"Education loans from Indian public-sector and private banks, as well as international lenders, are widely used to meet the balance. A well-prepared sponsor profile and early documentation materially improve the loan process, and EUROPA FUSION’s counsellors assist families with both.\", \"type\": \"cards\", \"items\": [{\"desc\": \"One-time grant of €5,000 for non-EEA students at participating institutions\", \"icon\": \"award\", \"meta\": \"How to apply: Applied for through the university; deadlines usually fall between February and May\", \"title\": \"NL Scholarship (formerly Holland Scholarship)\"}, {\"desc\": \"Merit-based awards such as Amsterdam Excellence, Maastricht NL-High Potential and TU Delft scholarships; some cover substantial fees\", \"icon\": \"trophy\", \"meta\": \"How to apply: Competitive; check each university’s page\", \"title\": \"Institutional awards\"}, {\"desc\": \"EU-funded awards covering tuition and a living allowance for selected consortium programmes\", \"icon\": \"globe-europe-africa\", \"meta\": \"How to apply: Apply directly to the programme\", \"title\": \"Erasmus Mundus Joint Masters\"}, {\"desc\": \"Country-specific awards, administered by Nuffic’s overseas offices\", \"icon\": \"stars\", \"meta\": \"How to apply: Availability has varied by country; confirm current status for India\", \"title\": \"Orange Tulip Scholarship\"}], \"style\": \"icon\", \"title\": \"Scholarships and Funding\", \"columns\": 2, \"eyebrow\": \"Financial awards\"}, {\"id\": \"work\", \"type\": \"cards\", \"items\": [{\"desc\": \"Non-EU students may work for <strong>up to 16 hours a week</strong> throughout the year, or full-time in June, July and August, but not both. In either case, the employer must obtain a work permit before the student begins. Internships that form part of the curriculum do not require the same permit.\", \"icon\": \"briefcase\", \"title\": \"During Your Studies\"}, {\"desc\": \"Graduates may apply for the <strong>Orientation Year (zoekjaar)</strong> permit within three years of graduating. It lasts <strong>12 months</strong>, allows free employment without a separate work permit, and facilitates transition to a highly skilled migrant permit with lower salary thresholds.\", \"icon\": \"mortarboard\", \"title\": \"After Graduation (Zoekjaar)\"}], \"style\": \"icon\", \"title\": \"Working and Building a Career\", \"columns\": 2, \"eyebrow\": \"Employment & residence\"}, {\"note\": \"Apply for the Orientation Year within three years of graduating; years spent on a study permit generally do not count towards long-term residence.\", \"type\": \"steps\", \"items\": [{\"desc\": \"VVR for the length of your degree\", \"title\": \"Student permit\"}, {\"desc\": \"12 months to work or seek employment\", \"title\": \"Orientation Year\"}, {\"desc\": \"Highly skilled migrant or other work permit\", \"title\": \"Skilled worker permit\"}, {\"desc\": \"After qualifying years of residence\", \"title\": \"Long-term residence\"}], \"title\": \"From student permit to long-term career\"}, {\"text\": \"Employers in engineering, information technology, logistics, finance and life sciences recruit actively among international graduates, and starting salaries of roughly €2,200 to €3,200 a month are commonly cited for graduate roles. Proficiency in Dutch, while not essential, widens the field considerably.\", \"type\": \"notice\"}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"cards\", \"intro\": \"EUROPA FUSION accompanies applicants from the first conversation to the day of arrival, with a single counsellor guiding each stage.\", \"items\": [{\"desc\": \"and programme shortlist\", \"icon\": \"compass\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Studielink and portals\", \"icon\": \"file-earmark-text\", \"title\": \"Applications\"}, {\"desc\": \"tailored, never templated\", \"icon\": \"pencil-square\", \"title\": \"SOP, LOR and CV\"}, {\"desc\": \"and education loans\", \"icon\": \"award\", \"title\": \"Scholarships\"}, {\"desc\": \"documents and mock interview\", \"icon\": \"passport\", \"title\": \"Visa readiness\"}, {\"desc\": \"flights, rooms, arrival\", \"icon\": \"airplane\", \"title\": \"Travel and housing\"}], \"style\": \"icon\", \"title\": \"How EUROPA FUSION Supports You\", \"columns\": 3, \"eyebrow\": \"Our commitment\"}, {\"rows\": [[\"Profile evaluation and shortlisting\", \"An honest assessment of your academic record, goals and budget, followed by a balanced list of programmes and institutions\"], [\"Applications and documents\", \"Preparation of Studielink and portal applications, together with a personalised statement of purpose, references and CV\"], [\"Scholarships and finance\", \"Guidance on scholarships, sponsor documentation and education-loan applications\"], [\"Visa preparation\", \"Review of the funds and documents required for the MVV and VVR, and a mock interview where relevant\"], [\"Travel and settlement\", \"Support with flights, accommodation, insurance and a pre-departure briefing\"]], \"type\": \"table\", \"columns\": [\"Service\", \"What it involves\"]}, {\"id\": \"faq\", \"type\": \"faq\", \"items\": [{\"a\": \"Not for every programme. Many Master’s courses do not ask for one, but some business, economics and quantitative programmes do. Always check the programme page.\", \"q\": \"Do I need a GMAT or GRE score?\"}, {\"a\": \"Not necessarily. A gap can be explained in a motivation letter, and backlogs are assessed by the individual programme. A strong narrative and recent achievement carry weight.\", \"q\": \"Are gap years or backlogs a barrier?\"}, {\"a\": \"Dutch research universities and universities of applied sciences are accredited, and their degrees are widely recognised internationally. Applicants who intend to return should check any profession-specific requirements.\", \"q\": \"Is a Dutch degree recognised in India?\"}, {\"a\": \"Switching is possible within some institutions but may affect your residence permit and study-progress record, so seek guidance from the university first.\", \"q\": \"Can I change programme after I arrive?\"}, {\"a\": \"Family members may apply for their own permits, subject to the IND’s conditions and income requirements. Please discuss your circumstances with a counsellor before applying.\", \"q\": \"Can my spouse or family join me?\"}, {\"a\": \"As early as possible, ideally as soon as you receive your offer. Housing is the most common difficulty for new international students.\", \"q\": \"When should I begin looking for accommodation?\"}, {\"a\": \"Not for English-taught degrees. Basic Dutch, however, helps with daily life, part-time work and later career prospects.\", \"q\": \"Will I need to learn Dutch?\"}, {\"a\": \"Allow six to nine months from first enquiry to arrival, since applications, scholarships, permit processing and housing run in sequence.\", \"q\": \"How long does the whole process take?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"Questions & answers\"}, {\"ctas\": [{\"label\": \"APPLY NOW — FREE COUNSELLING\", \"action\": \"counselling\"}], \"note\": \"<strong>Note:</strong> Fees, funds thresholds, deadlines, and immigration rules are revised periodically. Figures are indicative and should be verified with the Immigration and Naturalisation Service (ind.nl), Nuffic (studyinnl.org) and the chosen institution before applying.\", \"text\": \"Speak to our counsellor for a personalised assessment of your profile, a university shortlist, scholarship options and a visa plan. The first consultation is complimentary.\", \"type\": \"cta\", \"title\": \"Your Dutch chapter begins here\"}]',NULL,NULL,9,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (11,'study-in-poland','country',7,'Study in Poland','Poland','Earn an internationally recognised degree in Warsaw, Kraków, Wrocław and beyond, with EUROPA FUSION guiding every step of your journey.','[{\"ctas\": [{\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}, {\"label\": \"Book Consultation\", \"action\": \"counselling\"}], \"lead\": \"Earn an internationally recognised degree in Warsaw, Kraków, Wrocław and beyond, with EUROPA FUSION guiding every step of your journey.\", \"type\": \"hero\", \"title\": \"Where European Excellence Meets Exceptional Value\", \"eyebrow\": \"Study in Poland\", \"highlight\": \"Exceptional Value\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Among the lowest in the European Union\", \"label\": \"Monthly living costs\", \"value\": \"€400–800\"}, {\"sub\": \"Bachelor’s + Master’s under Bologna\", \"label\": \"Years of study\", \"value\": \"3 + 2\"}, {\"sub\": \"Across leading Polish universities\", \"label\": \"English-taught programmes\", \"value\": \"100s\"}, {\"sub\": \"Convenient travel across 29 countries\", \"label\": \"EU & Schengen Member\", \"value\": \"EU\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Poland has emerged as one of Europe’s most compelling study destinations, combining recognised European qualifications with remarkably accessible costs.\", \"items\": [{\"desc\": \"Degrees follow the European Higher Education Area framework, supporting recognition and mobility across Europe.\", \"icon\": \"patch-check\", \"title\": \"Europe-wide recognition\"}, {\"desc\": \"Tuition and living costs are among the lowest in the European Union, allowing students to invest in quality education with confidence.\", \"icon\": \"piggy-bank\", \"title\": \"Exceptional affordability\"}, {\"desc\": \"Poland is distinguished in medicine, engineering, information technology, business and finance, with a thriving technology and services economy.\", \"icon\": \"briefcase\", \"title\": \"Strong academic and career fields\"}, {\"desc\": \"As a member of the Schengen Area, Poland places much of Europe within easy reach for study, travel and work.\", \"icon\": \"globe-europe-africa\", \"title\": \"A European gateway\"}, {\"desc\": \"From the energy of Warsaw to the historic student life of Kraków, Wrocław and Poznań, Polish cities are safe, modern and welcoming.\", \"icon\": \"shield-check\", \"title\": \"A vibrant student environment\"}], \"style\": \"icon\", \"title\": \"A European Education of Exceptional Value\", \"columns\": 3, \"eyebrow\": \"Why Poland\"}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"The following institutions represent key destinations available to EUROPA FUSION students.\", \"items\": [{\"city\": \"Warsaw\", \"desc\": \"Poland’s leading comprehensive university, with strengths across the sciences, law, economics, humanities and social sciences.\", \"name\": \"University of Warsaw\", \"type\": \"Public University\"}, {\"city\": \"Kraków\", \"desc\": \"A major historic research university with distinguished programmes in medicine, sciences, humanities and law.\", \"name\": \"Jagiellonian University\", \"type\": \"Public University\"}, {\"city\": \"Warsaw\", \"desc\": \"A leading centre for engineering, information technology, architecture and applied sciences.\", \"name\": \"Warsaw University of Technology\", \"type\": \"Technical University\"}, {\"city\": \"Kraków\", \"desc\": \"Renowned for engineering, computer science, energy and materials, with strong industry cooperation.\", \"name\": \"AGH University of Krakow\", \"type\": \"Technical University\"}, {\"city\": \"Wrocław\", \"desc\": \"Known for engineering, architecture and technology, with a large and growing international community.\", \"name\": \"Wrocław University of Science and Technology\", \"type\": \"Technical University\"}, {\"city\": \"Poznań\", \"desc\": \"A comprehensive university recognised for the humanities, social sciences, natural sciences and modern languages.\", \"name\": \"Adam Mickiewicz University\", \"type\": \"Public University\"}, {\"city\": \"Warsaw\", \"desc\": \"A leading Polish institution for economics, finance, management, international business and quantitative analytics.\", \"name\": \"SGH Warsaw School of Economics\", \"type\": \"Specialist Institution\"}, {\"city\": \"Warsaw\", \"desc\": \"A specialist institution offering English-taught programmes in medicine (6-year MD), dentistry, pharmacy and health sciences.\", \"name\": \"Medical University of Warsaw\", \"type\": \"Medical University\"}], \"title\": \"Leading Polish Universities\", \"eyebrow\": \"Featured universities\"}, {\"id\": \"programmes\", \"rows\": [[\"Bachelor’s (Licencjat)\", \"3–3.5 years\", \"180–210\", \"Direct application to the university; many English-taught options, especially in business, IT and engineering.\"], [\"Engineering Bachelor’s (Inżynier)\", \"3.5 years\", \"210\", \"Applied technical degree combining theory with laboratory, coding and industry project work.\"], [\"Master’s degree\", \"1.5–2 years\", \"90–120\", \"A wide choice of English-taught programmes across business, technology, science and social sciences.\"], [\"Long-cycle Master’s\", \"5–6 years\", \"300–360\", \"Medicine, Dentistry, Pharmacy and Law; entrance examinations are common and entry is competitive.\"], [\"Doctoral studies (PhD)\", \"4 years\", \"—\", \"Research-focused study in a doctoral school, often with NAWA or state scholarship support.\"], [\"Postgraduate studies\", \"1–2 years\", \"Varies\", \"Professional specialisation for graduates, often part-time or in blended executive formats.\"]], \"type\": \"table\", \"chips\": [\"Medicine and Dentistry\", \"Engineering and Technology\", \"Information Technology and Data Science\", \"Business, Management and Finance\", \"Architecture and Design\", \"Pharmacy and Life Sciences\", \"Law and Social Sciences\", \"Arts and Humanities\"], \"intro\": \"Polish higher education follows the European Bologna model with clear undergraduate, master’s, and long-cycle medical routes.\", \"title\": \"Programmes and Qualifications in Poland\", \"columns\": [\"Qualification\", \"Duration\", \"Credits (ECTS)\", \"Notes & Focus\"], \"eyebrow\": \"Academic pathways\", \"chips_title\": \"Popular fields of study in Poland\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 6000, \"min\": 2000, \"label\": \"Tuition, non-medical programmes (per year)\", \"value\": \"≈ €2,000 - €6,000\"}, {\"max\": 13000, \"min\": 9500, \"label\": \"Tuition, medicine and dentistry (per year)\", \"value\": \"≈ €9,500 - €13,000\"}, {\"max\": 9600, \"min\": 4800, \"label\": \"Living costs (per year)\", \"value\": \"≈ €4,800 - €9,600\"}, {\"max\": 7000, \"min\": 3500, \"label\": \"Typical visa funds benchmark (per year)\", \"value\": \"≈ €3,500 - €7,000\"}], \"type\": \"costs\", \"cards\": [{\"desc\": \"Programmes administered by Poland’s National Agency for Academic Exchange supporting international students.\", \"title\": \"NAWA Scholarships\"}, {\"desc\": \"EU-funded mobility and joint-degree opportunities for eligible students across Europe.\", \"title\": \"Erasmus+ & Mundus\"}, {\"desc\": \"Merit-based tuition reductions and academic awards offered directly by individual Polish universities.\", \"title\": \"University Merit Awards\"}], \"intro\": \"A clear view of costs allows you to plan with confidence. Indicative annual ranges in euros:\", \"title\": \"Understanding the Investment in Poland\", \"eyebrow\": \"Fees & funding\", \"scale_max\": 17500, \"cards_title\": \"Scholarships & funding\", \"chart_title\": \"Indicative annual investment in Poland\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"EUROPA FUSION offers a structured, transparent process so that each stage is handled with care and precision.\", \"items\": [{\"desc\": \"Academic record, career goals, budget and preferred city are reviewed to define a realistic shortlist.\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Courses are matched to your profile, with attention to language of instruction, entry tests and deadlines.\", \"title\": \"Programme & university selection\"}, {\"desc\": \"Transcripts, certificates, language proof, CV, motivation letter and passport are prepared and submitted directly.\", \"title\": \"Application to the university\"}, {\"desc\": \"Where required, preparation for entrance examinations or interviews, for example for medical and technical programmes.\", \"title\": \"Entrance assessment\"}, {\"desc\": \"Acceptance of your offer, issue of the official admission letter and payment of the first instalment of tuition.\", \"title\": \"Admission & tuition confirmation\"}, {\"desc\": \"Preparation of the national visa file, including proof of funds, accommodation evidence and compliant health insurance.\", \"title\": \"Student visa (Type D)\"}, {\"desc\": \"Application for the temporary residence permit (Karta Pobytu) before visa expiry, followed by accommodation and orientation.\", \"title\": \"Arrival & residence permit\"}], \"title\": \"From Enquiry to Enrolment\", \"eyebrow\": \"Your admission journey\"}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"cards\", \"intro\": \"We believe a student’s journey abroad should be guided with the same rigour as the education it leads to.\", \"items\": [{\"desc\": \"Personalised shortlisting and strategy from first enquiry to offer.\", \"icon\": \"compass\", \"title\": \"Admissions Counselling\"}, {\"desc\": \"Careful preparation of statements of purpose, CVs and supporting documents.\", \"icon\": \"file-earmark-text\", \"title\": \"Application Excellence\"}, {\"desc\": \"Support with NAWA, Erasmus+ and Polish university scholarship options.\", \"icon\": \"award\", \"title\": \"Scholarship Guidance\"}, {\"desc\": \"Structured assistance with national Type D visa documentation and financial evidence.\", \"icon\": \"passport\", \"title\": \"Visa Support\"}, {\"desc\": \"Guidance on student dormitories and private student flats in Warsaw, Kraków and Wrocław.\", \"icon\": \"house-door\", \"title\": \"Accommodation Support\"}, {\"desc\": \"Briefings before you fly and continued support after you arrive in Poland.\", \"icon\": \"airplane\", \"title\": \"Pre-Departure & Beyond\"}], \"style\": \"icon\", \"title\": \"Your Partner for the Journey\", \"columns\": 3, \"eyebrow\": \"Why EUROPA FUSION\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Common questions about studying and settling in Poland.\", \"items\": [{\"a\": \"Yes. Polish universities offer a large and growing selection of English-taught programmes at Bachelor’s, Master’s and doctoral level, including medicine and dentistry.\", \"q\": \"Can I study in Poland entirely in English?\"}, {\"a\": \"It is not required for English-taught programmes, but basic Polish is very helpful for daily life, part-time work and career prospects. Polish-taught programmes require certified proficiency, typically at B2 level.\", \"q\": \"Do I need to speak Polish?\"}, {\"a\": \"Poland is one of Europe’s most affordable destinations. Tuition for non-medical programmes is commonly in the range of €2,000 to €6,000 per year, while medical programmes cost considerably more (€9,500–€13,000/yr). Monthly living costs typically range from €400 to €800.\", \"q\": \"How much does it cost to study in Poland?\"}, {\"a\": \"The main intake begins in October, with a smaller intake in February or March at some universities. Many institutions admit on a rolling basis, though earlier application improves visa timing. Begin preparing at least 6 to 9 months in advance.\", \"q\": \"When are the intakes and deadlines?\"}, {\"a\": \"Most Bachelor’s and Master’s programmes assess applicants on their academic record and a motivation letter. Medicine, dentistry and certain other programmes require entrance examinations or interviews.\", \"q\": \"Do I need to take an entrance examination?\"}, {\"a\": \"Universities usually accept IELTS, TOEFL or an equivalent, and some conduct their own interview or test. Requirements differ by institution.\", \"q\": \"Which English-language tests are accepted?\"}, {\"a\": \"Applicants must demonstrate sufficient funds for their stay. In practice consulates and universities expect proof of around €3,500 to €7,000 for the first year, often alongside payment of the first tuition instalment.\", \"q\": \"How much money must I show for the student visa?\"}, {\"a\": \"Full-time students at accredited Polish institutions may generally work part-time without a separate work permit during their studies. You should always maintain academic attendance as priority.\", \"q\": \"Can I work while studying in Poland?\"}, {\"a\": \"Graduates may apply for a temporary residence permit to look for work or start a business, for a period set by current regulations (typically 9-12 months), and may then transition to a full work permit or Blue Card.\", \"q\": \"Can I remain in Poland after graduating?\"}, {\"a\": \"Yes. Options include NAWA programmes (e.g. Banach or Gen. Anders), Erasmus+, and merit-based fee reductions from individual universities. Competition is strong and deadlines are early.\", \"q\": \"Are scholarships available for international students?\"}, {\"a\": \"Students may choose university dormitories, which are typically the most economical option (PLN 480 to PLN 1,100 / month, approx €110–€250), or private shared rentals in Warsaw, Kraków and Wrocław.\", \"q\": \"What are accommodation options?\"}, {\"a\": \"Typically: passport, academic transcripts and certificates (with apostille/legalisation and sworn translation if needed), language-test results, CV, motivation letter, proof of financial means, proof of accommodation and health insurance.\", \"q\": \"What documents will I need?\"}, {\"a\": \"We assist at every stage: profile assessment, university selection, application and document preparation, scholarship guidance, visa support, accommodation and pre-departure briefing.\", \"q\": \"How does EUROPA FUSION support my application?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"FAQ\"}, {\"ctas\": [{\"label\": \"Book Free Consultation\", \"action\": \"counselling\"}, {\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}], \"text\": \"Speak with a EUROPA FUSION counsellor for a personalised university shortlist and a clear roadmap to your offer letter.\", \"type\": \"cta\", \"title\": \"Begin Your Polish Chapter\"}]',NULL,NULL,10,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (12,'study-in-spain','country',5,'Study in Spain','Spain','Earn a respected European degree in Madrid, Barcelona, Valencia and beyond, with EUROPA FUSION guiding every step of your journey.','[{\"ctas\": [{\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}, {\"label\": \"Book Consultation\", \"action\": \"counselling\"}], \"lead\": \"Earn a respected European degree in Madrid, Barcelona, Valencia and beyond, with EUROPA FUSION guiding every step of your journey.\", \"type\": \"hero\", \"title\": \"Where Mediterranean Energy Meets Academic Ambition\", \"eyebrow\": \"Study in Spain\", \"highlight\": \"Academic Ambition\"}, {\"type\": \"stats\", \"items\": [{\"sub\": \"Language of international business & culture\", \"label\": \"Global Spanish speakers\", \"value\": \"500M+\"}, {\"sub\": \"For university students on student visa\", \"label\": \"Weekly work allowance\", \"value\": \"30 hrs\"}, {\"sub\": \"Grado (Bachelor’s) + Máster\", \"label\": \"Years of study\", \"value\": \"4 + 1–2\"}, {\"sub\": \"100% of IPREM living metric\", \"label\": \"Annual visa funds benchmark\", \"value\": \"€7,200\"}]}, {\"id\": \"why\", \"type\": \"cards\", \"intro\": \"Spain combines internationally respected universities and business schools with an outstanding quality of life and costs that compare favourably with other global study hubs.\", \"items\": [{\"desc\": \"Degrees follow the European Higher Education Area framework, supporting recognition and mobility across Europe.\", \"icon\": \"patch-check\", \"title\": \"Europe-wide recognition\"}, {\"desc\": \"Spain’s universities and business schools are world-renowned in business, engineering, architecture, design, health sciences, tourism and social sciences.\", \"icon\": \"bank\", \"title\": \"Academic strengths\"}, {\"desc\": \"Mastery of Spanish opens professional career horizons across Europe, Latin America and global international organizations.\", \"icon\": \"globe-europe-africa\", \"title\": \"A global language\"}, {\"desc\": \"University students on a student visa may work up to 30 hours per week, and eligible graduates can explore stay-back permits to work.\", \"icon\": \"briefcase\", \"title\": \"Practical career pathways\"}, {\"desc\": \"From Madrid to Barcelona and Valencia, student life is vibrant, sociable, safe and outdoors-oriented with a pleasant Mediterranean climate.\", \"icon\": \"shield-check\", \"title\": \"An exceptional lifestyle\"}], \"style\": \"icon\", \"title\": \"A Distinguished Education in One of Europe’s Most Dynamic Countries\", \"columns\": 3, \"eyebrow\": \"Why Spain\"}, {\"id\": \"universities\", \"type\": \"universities\", \"intro\": \"The following institutions represent key destinations available to EUROPA FUSION students.\", \"items\": [{\"city\": \"Madrid\", \"desc\": \"One of Spain’s largest and oldest universities, offering an exceptionally broad range of programmes in humanities, sciences, law and health.\", \"name\": \"Complutense University of Madrid\", \"type\": \"Public University\"}, {\"city\": \"Madrid\", \"desc\": \"A premier research-led university widely respected for sciences, medicine, economics, biotechnology and the humanities.\", \"name\": \"Autonomous University of Madrid\", \"type\": \"Public University\"}, {\"city\": \"Madrid\", \"desc\": \"Known for law, social sciences, business, economics and engineering, with a strongly international and employment-focused profile.\", \"name\": \"Carlos III University of Madrid\", \"type\": \"Public University\"}, {\"city\": \"Barcelona\", \"desc\": \"A comprehensive research university with notable strengths in health sciences, humanities, life sciences, economics and the arts.\", \"name\": \"University of Barcelona\", \"type\": \"Public University\"}, {\"city\": \"Barcelona\", \"desc\": \"A top-ranked modern institution distinguished for economics, political science, communication, law and data science.\", \"name\": \"Pompeu Fabra University\", \"type\": \"Public University\"}, {\"city\": \"Valencia\", \"desc\": \"A leading destination for engineering, computer science, architecture, design and applied technology, with close industry links.\", \"name\": \"Polytechnic University of Valencia\", \"type\": \"Technical University\"}, {\"city\": \"Madrid & Segovia\", \"desc\": \"An internationally oriented private university and business school focused on business, technology, law, leadership and innovation.\", \"name\": \"IE University\", \"type\": \"Private University\"}, {\"city\": \"Barcelona\", \"desc\": \"Internationally recognized for management, business administration and law programmes, with a global alumni and corporate network.\", \"name\": \"ESADE Business School\", \"type\": \"Private Business School\"}], \"title\": \"Distinguished Institutions in Spain\", \"eyebrow\": \"Featured universities\"}, {\"id\": \"programmes\", \"rows\": [[\"Grado (Bachelor’s)\", \"4 years\", \"240\", \"Requires recognised secondary qualifications and UNEDasiss accreditation for non-EU applicants; many degrees taught in Spanish.\"], [\"Máster Universitario (Master’s)\", \"1–2 years\", \"60–120\", \"The broadest selection of English-taught programmes, especially in business, technology and social sciences.\"], [\"Single-cycle degrees\", \"5–6 years\", \"300–360\", \"Medicine, Dentistry, Veterinary Science and Architecture; highly competitive direct admission.\"], [\"Doctorado (PhD)\", \"3–4 years\", \"—\", \"Research-focused study within university doctoral schools, with university and national research grants.\"], [\"Formación Profesional (Higher Vocational)\", \"2 years\", \"—\", \"Applied, employer-linked practical qualifications, generally delivered in Spanish.\"], [\"Private university & business schools\", \"Varies\", \"Varies\", \"Smaller cohorts, global faculty, cutting-edge corporate networking, and extensive English-taught curricula.\"]], \"type\": \"table\", \"chips\": [\"Business, Management and Finance\", \"Engineering and Technology\", \"Architecture and Design\", \"Hospitality and Tourism\", \"Medicine and Health Sciences\", \"Data Science and Artificial Intelligence\", \"Marketing and Communication\", \"Languages, Arts and Humanities\"], \"intro\": \"Spanish higher education offers 4-year Grado undergraduate programmes and specialized 1-2 year Máster degrees.\", \"title\": \"Programmes and Qualifications in Spain\", \"columns\": [\"Qualification\", \"Duration\", \"Credits (ECTS)\", \"Notes & Focus\"], \"eyebrow\": \"Academic pathways\", \"chips_title\": \"Popular fields of study in Spain\"}, {\"id\": \"costs\", \"rows\": [{\"max\": 2500, \"min\": 700, \"label\": \"Public university Bachelor\'s tuition (per year)\", \"value\": \"≈ €700 - €2,500\"}, {\"max\": 5000, \"min\": 1000, \"label\": \"Public university Master\'s tuition (per year)\", \"value\": \"≈ €1,000 - €5,000\"}, {\"max\": 20000, \"min\": 6000, \"label\": \"Private university tuition (per year)\", \"value\": \"≈ €6,000 - €20,000+\"}, {\"max\": 16800, \"min\": 9600, \"label\": \"Living costs (per year)\", \"value\": \"≈ €9,600 - €16,800\"}, {\"max\": 7200, \"min\": 7200, \"label\": \"Visa funds benchmark (IPREM per year)\", \"value\": \"€7,200\"}], \"type\": \"costs\", \"cards\": [{\"desc\": \"Merit and need-based tuition waivers, bursaries, and discounts offered directly by universities and business schools.\", \"title\": \"Institutional Scholarships\"}, {\"desc\": \"Funding programmes offered by Spanish Autonomous Communities and national educational ministries.\", \"title\": \"Regional & National Awards\"}, {\"desc\": \"EU-funded joint Master’s degrees that include full tuition waivers and generous living stipends.\", \"title\": \"Erasmus Mundus\"}], \"intro\": \"A clear view of costs allows you to plan with confidence. Indicative annual ranges in euros:\", \"title\": \"Understanding the Investment in Spain\", \"eyebrow\": \"Fees & funding\", \"scale_max\": 25000, \"cards_title\": \"Scholarships & funding\", \"chart_title\": \"Indicative annual investment in Spain\"}, {\"id\": \"journey\", \"type\": \"steps\", \"intro\": \"EUROPA FUSION offers a structured, transparent process so that each stage is handled with care and precision.\", \"items\": [{\"desc\": \"Academic record, career goals, budget and preferred city are reviewed to define a realistic shortlist.\", \"title\": \"Profile evaluation\"}, {\"desc\": \"Courses are matched to your profile, with attention to language of instruction, admission procedure and deadlines.\", \"title\": \"Programme & university selection\"}, {\"desc\": \"Transcripts, certificates, language proof, CV, motivation letter and passport are prepared and submitted through university portals.\", \"title\": \"Documents & application\"}, {\"desc\": \"Where required, preparation for UNEDasiss access accreditation for Bachelor’s study, and legalisation of documents for Master’s.\", \"title\": \"Access accreditation & recognition\"}, {\"desc\": \"Offer acceptance, payment of the enrolment deposit and receipt of the official university admission letter.\", \"title\": \"Admission & enrolment confirmation\"}, {\"desc\": \"Preparation of the long-stay student visa file, including proof of funds (IPREM), private health insurance and criminal-record clearance.\", \"title\": \"Student visa application\"}, {\"desc\": \"Foreigner identity card (TIE) registration, accommodation settlement, NIE number and orientation to student life in Spain.\", \"title\": \"Arrival & settling in\"}], \"title\": \"From Enquiry to Enrolment\", \"eyebrow\": \"Your admission journey\"}, {\"id\": \"support\", \"tone\": \"dark\", \"type\": \"cards\", \"intro\": \"We believe a student’s journey abroad should be guided with the same rigour as the education it leads to.\", \"items\": [{\"desc\": \"Personalised shortlisting and strategy from first enquiry to offer.\", \"icon\": \"compass\", \"title\": \"Admissions Counselling\"}, {\"desc\": \"Careful preparation of statements of purpose, CVs and supporting documents.\", \"icon\": \"file-earmark-text\", \"title\": \"Application Excellence\"}, {\"desc\": \"Support with university, regional and national scholarship options.\", \"icon\": \"award\", \"title\": \"Scholarship Guidance\"}, {\"desc\": \"Structured assistance with student visa documentation, IPREM proof, and translations.\", \"icon\": \"passport\", \"title\": \"Visa Support\"}, {\"desc\": \"Guidance on Colegios Mayores and shared student flats in Madrid, Barcelona and Valencia.\", \"icon\": \"house-door\", \"title\": \"Accommodation Support\"}, {\"desc\": \"Briefings before you fly, TIE registration support, and continuous advisory.\", \"icon\": \"airplane\", \"title\": \"Pre-Departure & Beyond\"}], \"style\": \"icon\", \"title\": \"Your Partner for the Journey\", \"columns\": 3, \"eyebrow\": \"Why EUROPA FUSION\"}, {\"id\": \"faq\", \"type\": \"faq\", \"intro\": \"Common questions about studying and settling in Spain.\", \"items\": [{\"a\": \"Yes. Spain offers a wide choice of English-taught programmes, particularly at Master’s level and at private universities and business schools. Many public Bachelor’s programmes are taught in Spanish, so the language of instruction should be confirmed for each course.\", \"q\": \"Can I study in Spain entirely in English?\"}, {\"a\": \"It is not required for English-taught programmes, but Spanish greatly enhances daily life, part-time work and career prospects. For Spanish-taught degrees, certified proficiency (such as DELE or SIELE B2) is requested.\", \"q\": \"Do I need to speak Spanish?\"}, {\"a\": \"Public university tuition is set by each regional autonomous community and charged per credit (€700 to €2,500/yr for Bachelor’s; €1,000 to €5,000/yr for Master’s). Private universities charge €6,000 to €20,000+. Living costs commonly range from €800 to €1,400 per month.\", \"q\": \"How much does it cost to study in Spain?\"}, {\"a\": \"The main intake begins in September or October, with a smaller number of programmes starting in February. Application windows at public universities typically fall in the spring and early summer (April–June). Early preparation is advisable.\", \"q\": \"When are the intakes and deadlines?\"}, {\"a\": \"Most English-taught programmes request IELTS (typically 6.0–7.0), TOEFL, or equivalent tests.\", \"q\": \"Which English-language tests are accepted?\"}, {\"a\": \"Applicants must demonstrate sufficient funds benchmarked at 100% of the IPREM (approx. €600 per month, or €7,200 for a twelve-month stay), excluding tuition fees.\", \"q\": \"How much money must I show for the student visa?\"}, {\"a\": \"University students holding a student visa in Spain may generally work up to 30 hours per week, provided the employment is compatible with study hours.\", \"q\": \"Can I work while studying in Spain?\"}, {\"a\": \"Yes. Graduates may apply for a 1-year residence permit to look for employment or launch a business startup, or modify their status directly to an employment contract or EU Blue Card.\", \"q\": \"Can I remain in Spain after graduating?\"}, {\"a\": \"Yes. Spanish universities, regional governments, and private foundations offer merit and need-based tuition waivers, while Erasmus Mundus provides full scholarships for selected Master’s degrees.\", \"q\": \"Are scholarships available for international students?\"}, {\"a\": \"Options include Colegios Mayores (university residences), shared flats (*pisos compartidos*), and private purpose-built student housing across Madrid, Barcelona, and Valencia.\", \"q\": \"What are accommodation options?\"}, {\"a\": \"Typically: passport, academic transcripts and degrees (apostilled & translated), language certificate, CV, motivation letter, medical certificate, police clearance certificate, and proof of €7,200+ IPREM funds.\", \"q\": \"What documents will I need?\"}, {\"a\": \"We handle profile evaluation, UNEDasiss accreditation guidance, document legalization/sworn translations, university applications, Spanish visa file processing, and housing search.\", \"q\": \"How does EUROPA FUSION support my application?\"}], \"title\": \"Frequently Asked Questions\", \"eyebrow\": \"FAQ\"}, {\"ctas\": [{\"label\": \"Book Free Consultation\", \"action\": \"counselling\"}, {\"label\": \"Free Profile Evaluation\", \"action\": \"evaluation\"}], \"text\": \"Speak with a EUROPA FUSION counsellor for a personalised university shortlist and a clear roadmap to your offer letter.\", \"type\": \"cta\", \"title\": \"Begin Your Spanish Chapter\"}]',NULL,NULL,11,1,'2026-11-22 12:47:54','2026-11-22 13:11:34');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (13,'privacy-policy','legal',NULL,'Privacy Policy','Privacy Policy','Privacy Policy of EUROPA FUSION PRIVATE LIMITED – how we handle your information, our services and your rights.',NULL,'<h2>1. Introduction &amp; Overview</h2>\n<p>Welcome to <strong>EUROPA FUSION PRIVATE LIMITED</strong> (CIN: U80302TN2021PTC146401), a premium overseas education guidance organisation having its registered office at Office No. 715A, Spencer Plaza, Anna Salai, Chennai, Tamil Nadu – 600002.</p>\n<p>We respect your privacy and are committed to protecting your personal information. This Privacy Policy outlines our practices concerning the collection, use, disclosure, and safeguarding of information when you interact with our website (<a href=\"https://europafusion.io\">europafusion.io</a>), consult with our counselors, or use our admission guidance services.</p>\n<h2>2. Information We Collect</h2>\n<p>To facilitate admissions and accurate profile assessment, we collect personal and academic data provided voluntarily by students, parents, and guardians, including:</p>\n<ul>\n  <li><strong>Contact Details:</strong> Full name, email address, phone/WhatsApp number, residential address.</li>\n  <li><strong>Academic Profile:</strong> Transcripts, marksheets, bachelor/master degree certificates, GPA/percentage, standardized test scores (IELTS, TOEFL, GRE, GMAT, TestAS, dMAT).</li>\n  <li><strong>Application Documents:</strong> Statement of Purpose (SOP), Letters of Recommendation (LOR), Curriculum Vitae (CV), portfolio files, passport details for application processing.</li>\n  <li><strong>Financial &amp; Visa Information:</strong> Proof of funds, blocked account details, or sponsorship documentation needed for visa consultation.</li>\n  <li><strong>Technical &amp; Usage Data:</strong> IP address, device type, browser information, pages visited on our portal to improve user experience.</li>\n</ul>\n<h2>3. How We Use Your Information</h2>\n<p>We strictly use student information for legitimate educational and application guidance purposes:</p>\n<ul>\n  <li>Evaluating academic qualifications against country and university entrance criteria (e.g. Germany, Finland, Ireland, France, Sweden, Netherlands).</li>\n  <li>Preparing, processing, and submitting applications to universities, uni-assist, APS India, or designated application portals.</li>\n  <li>Assisting with appointment scheduling for VFS, embassy visa filings, blocked account setups, and health insurance.</li>\n  <li>Providing structured prep materials for the Digital Master\'s Assessment Test (dMAT) and German language learning programs.</li>\n  <li>Communicating updates, application status, dead-lines, and admission offers via email, telephone, or WhatsApp.</li>\n</ul>\n<h2>4. Data Sharing &amp; Third Parties</h2>\n<p><strong>We do not sell, rent, or trade your personal information.</strong> Your information is only shared with authorized third parties strictly required to process your studies:</p>\n<ul>\n  <li>Accredited partner universities, public universities, admission committees, and processing platforms (e.g. Uni-Assist, Hochschulstart).</li>\n  <li>Official verification agencies and diplomatic missions (e.g., APS India, German Embassy, Consulates, VFS Global).</li>\n  <li>Licensed service partners offering student accommodation, blocked accounts, educational loans, and student health insurance (only upon explicit student request).</li>\n  <li>Legal or regulatory authorities if mandated by law or court order.</li>\n</ul>\n<h2>5. Data Protection &amp; Security</h2>\n<p>We deploy strict physical, electronic, and administrative safeguards to protect your personal files against unauthorized access, alteration, or disclosure. All sensitive files are stored on secure servers with restricted employee access limited only to authorized counsellors and document processors.</p>\n<h2>6. Your Privacy Rights</h2>\n<p>As a student or parent, you have full control over your personal records:</p>\n<ul>\n  <li>Right to access, verify, or update your submitted personal and academic data.</li>\n  <li>Right to request deletion of your contact records from promotional and marketing lists.</li>\n  <li>Right to revoke consent for university application processing at any time (subject to active application deadlines).</li>\n</ul>\n<h2>7. Contact Us Regarding Privacy</h2>\n<p>If you have questions, concerns, or requests regarding this Privacy Policy or data security, please contact our grievance officer:</p>\n<p>EUROPA FUSION PRIVATE LIMITED</p>\n<p>Office No. 715A, Spencer Plaza, Anna Salai, Chennai, Tamil Nadu – 600002</p>\n<p>contact@europafusion.io</p>\n<p>+91 99747 98803</p>','2026-01-01',100,1,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (14,'terms-conditions','legal',NULL,'Terms & Conditions','Terms & Conditions','Terms & Conditions of EUROPA FUSION PRIVATE LIMITED – how we handle your information, our services and your rights.',NULL,'<p>Governing your relationship with EUROPA FUSION PRIVATE LIMITED</p>\n<h2>1. Acceptance of Terms</h2>\n<p>These Terms &amp; Conditions constitute a legally binding agreement between you (the \"Student\", \"Client\", or \"User\") and <strong>EUROPA FUSION PRIVATE LIMITED</strong> (CIN: U80302TN2021PTC146401).</p>\n<p>By registering on our website, scheduling a consultation, or engaging our overseas education services, you acknowledge that you have read, understood, and agreed to be bound by these Terms and our Privacy Policy.</p>\n<h2>2. Scope of Services</h2>\n<p>EUROPA FUSION provides advisory, counseling, and logistical support services for international education, including:</p>\n<ul>\n  <li>Academic profile evaluation and eligibility verification.</li>\n  <li>University and degree program recommendations across Germany, Finland, Ireland, France, Sweden, Netherlands, and other European study destinations.</li>\n  <li>Guidance on drafting application documentation, such as Statements of Purpose (SOP), Letters of Recommendation (LOR), and Resumes (CV).</li>\n  <li>Digital Master\'s Assessment Test (dMAT) preparation guidance and German language training support.</li>\n  <li>Application submission coordination (Uni-Assist, direct portals) and visa interview/documentation preparation.</li>\n</ul>\n<h2>3. Student Responsibilities &amp; Authenticity</h2>\n<p>Students entering into an agreement with EUROPA FUSION agree to the following obligations:</p>\n<ul>\n  <li><strong>Accuracy of Records:</strong> You warrant that all academic transcripts, certificates, identity proofs, and test scores provided are genuine, authentic, and free from misrepresentation.</li>\n  <li><strong>Adherence to Deadlines:</strong> You agree to provide required documentation in a timely manner according to strict university and visa application windows.</li>\n  <li><strong>Zero Tolerance for Fraud:</strong> Submission of forged documents, fabricated financial statements, or false academic credentials will lead to immediate service termination with no entitlement to refund, and may be reported to relevant authorities.</li>\n</ul>\n<h2>4. Absolute Disclaimer of Admission &amp; Visa Guarantees</h2>\n<p>Important Notice: EUROPA FUSION is an independent educational consulting firm. We do NOT guarantee admission into any university or the issuance of any student visa.</p>\n<p>Final admission decisions reside solely with the respective university admissions committees based on merit, capacity, and academic criteria. Visa issuance is exclusively within the sovereign discretion of the respective embassies, consulates, and immigration authorities.</p>\n<h2>5. Fees &amp; Third-Party Expenses</h2>\n<p>Service fees paid to EUROPA FUSION cover advisory and documentation assistance only. Students are solely responsible for all external third-party costs, including but not limited to university application fees (Uni-Assist, portals), APS verification charges, standardized examination fees (IELTS, TOEFL, GRE, dMAT), embassy visa fees, courier charges, blocked account deposits, and health insurance premiums.</p>\n<h2>6. Intellectual Property</h2>\n<p>All logos, trademarks, website content, dMAT guidance modules, test prep strategies, and proprietary advisory frameworks are the exclusive intellectual property of <strong>EUROPA FUSION PRIVATE LIMITED</strong>. Reproduction or unauthorized distribution without express written consent is strictly prohibited.</p>\n<h2>7. Limitation of Liability</h2>\n<p>To the maximum extent permitted by applicable law, EUROPA FUSION PRIVATE LIMITED and its directors, employees, and consultants shall not be held liable for any indirect, incidental, punitive, or consequential damages resulting from university rejections, visa refusals, changes in immigration policies, or student delays.</p>\n<h2>8. Governing Law &amp; Jurisdiction</h2>\n<p>These Terms &amp; Conditions shall be governed by and construed in accordance with the laws of India. Any disputes arising out of or related to these terms shall be subject to the exclusive jurisdiction of the competent courts in <strong>Chennai, Tamil Nadu, India</strong>.</p>','2026-01-01',101,1,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (15,'disclaimer','legal',NULL,'Legal Disclaimer','Legal Disclaimer','Legal Disclaimer of EUROPA FUSION PRIVATE LIMITED – how we handle your information, our services and your rights.',NULL,'<p>Official disclosures by EUROPA FUSION PRIVATE LIMITED</p>\n<h2>1. Nature of Advisory Services</h2>\n<p><strong>EUROPA FUSION PRIVATE LIMITED</strong> (CIN: U80302TN2021PTC146401) is an independent overseas education advisory consultancy. We provide profile assessment, counseling, documentation review, and procedural assistance.</p>\n<p>We do NOT act as an official university admissions committee, nor are we an embassy, consular office, or sovereign immigration authority.</p>\n<h2>2. University Admissions Disclaimer</h2>\n<p>All university admissions, including tuition-free public universities in Germany and top universities in Finland, France, Ireland, Netherlands, Sweden, etc., are granted solely at the discretion of the respective institution\'s admissions board.</p>\n<ul>\n  <li>No agent, counselor, or employee of EUROPA FUSION is authorized to promise or guarantee an admission letter.</li>\n  <li>Admissions are based strictly on academic merit, ECTS credit matching, subject prerequisites, GPA requirements, language scores, and program seat limits.</li>\n  <li>University tuition policies (e.g. €0 public university tuition in Germany) are set by sovereign state ministries and may be subject to legislative revisions beyond our control.</li>\n</ul>\n<h2>3. Visa &amp; Immigration Authority Disclaimer</h2>\n<p>Visa issuance and entry permits are the sovereign privilege of the respective destination country\'s government:</p>\n<ul>\n  <li>Neither EUROPA FUSION nor its affiliates can influence, expedite, or guarantee the outcome of any visa, residence permit, or APS verification.</li>\n  <li>Decisions are made entirely by the relevant Embassy, Consulate-General, Ausländerbehörde (Foreigners Authority), or immigration department.</li>\n  <li>Processing timelines, appointment slot availability (VFS/Embassy), and financial requirements (such as blocked account amounts) are determined solely by government bodies.</li>\n</ul>\n<h2>4. dMAT &amp; Test Preparation Guidance</h2>\n<p>EUROPA FUSION provides coaching frameworks, orientation, and preparatory guidance for the Digital Master\'s Assessment Test (dMAT) and language proficiencies. Performance on any standardized test depends entirely on the student\'s individual aptitude, dedication, and study efforts. We do not guarantee specific percentile rankings or test outcomes.</p>\n<h2>5. Website Content Accuracy</h2>\n<p>While we strive to ensure that all information on <a href=\"https://europafusion.io\">europafusion.io</a> regarding course requirements, university deadlines, post-study work permits, and living costs is accurate and up-to-date, institutional guidelines and immigration rules change frequently. Students are strongly advised to verify details with our advisors and official university websites.</p>\n<h2>6. External Links &amp; Third-Party Resources</h2>\n<p>Our website and resources may contain links to external government portals, university registries, APS India, Uni-Assist, and student banking platforms. EUROPA FUSION does not control, endorse, or assume responsibility for the content, privacy practices, or availability of third-party websites.</p>','2026-01-01',102,1,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `pages` (`id`, `slug`, `kind`, `destination_id`, `title`, `nav_label`, `meta_description`, `sections`, `body`, `last_updated`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (16,'refund-policy','legal',NULL,'Refund Policy','Refund Policy','Refund Policy of EUROPA FUSION PRIVATE LIMITED – how we handle your information, our services and your rights.',NULL,'<p>Clear, transparent terms by EUROPA FUSION PRIVATE LIMITED</p>\n<h2>1. Overview &amp; Scope</h2>\n<p>This Refund &amp; Cancellation Policy sets forth the terms and conditions under which <strong>EUROPA FUSION PRIVATE LIMITED</strong> (CIN: U80302TN2021PTC146401) processes service cancellations and refund requests for student consulting, application processing, dMAT prep, and related educational services.</p>\n<p>We are dedicated to honest, student-first guidance. Our policies are designed to be equitable, transparent, and compliant with all statutory consumer protection norms in India.</p>\n<h2>2. Service Fees &amp; Consultation Tiers</h2>\n<p>Initial discovery calls and profile evaluations provided through our website or helpline are completely free of charge. Where students enroll in structured consulting programs, university application packages, or dMAT test coaching, fees are agreed upon in advance and outlined in the student onboarding agreement.</p>\n<h2>3. Eligibility for Refund</h2>\n<p>Refund eligibility depends on the stage of work initiated:</p>\n<ul>\n  <li><strong>Cooling-off Period (Within 48 hours):</strong> If a student enrolls and decides to withdraw within 48 hours of payment, and before any university shortlisting, document drafting (SOP/LOR/CV), or test coaching has begun, a 100% refund of the consultancy fee (minus administrative/gateway processing charges of 5%) will be issued.</li>\n  <li><strong>Prior to Application Submission:</strong> If a student cancels after profile assessment and shortlisting but before any university application is drafted or processed, up to 50% of the consultancy fee is eligible for refund, reflecting advisory time invested.</li>\n  <li><strong>After Application Lodgement:</strong> Once university applications have been finalized, submitted to Uni-Assist, university portals, or APS India, the professional service fee is deemed fully rendered and non-refundable.</li>\n</ul>\n<h2>4. Strictly Non-Refundable Expenses</h2>\n<p>The following external expenses are strictly non-refundable under all circumstances:</p>\n<ul>\n  <li>Third-party university application fees (e.g. Uni-Assist assessment fees, direct university application charges).</li>\n  <li>APS (Akademische Prüfstelle) verification fees paid directly to the Science Section of the German Embassy.</li>\n  <li>Language test registration fees (IELTS, TOEFL, Goethe-Zertifikat, TestDaF) and official test exam centers.</li>\n  <li>Embassy/Consular visa appointment fees, VFS processing charges, and translation/notarization costs.</li>\n  <li>Payments made directly to blocked account providers (Expatrio, Fintiba, Coracle) or health insurance companies.</li>\n</ul>\n<h2>5. Rejection &amp; Disqualification Grounds</h2>\n<p>No refund shall be granted if a university rejects an application due to student-submitted fraudulent documents, academic forgery, failure to attend mandatory interviews, failure to take the dMAT or language exams, or missed deadlines caused by student delays.</p>\n<h2>6. Refund Processing Method &amp; Timelines</h2>\n<p>Approved refund claims will be processed strictly as follows:</p>\n<ul>\n  <li>Refund requests must be formally submitted in writing via email to <a href=\"mailto:contact@europafusion.io\">contact@europafusion.io</a> with the payment receipt and student registration ID.</li>\n  <li>Refund requests are reviewed by our finance committee within <strong>5 business days</strong> of receipt.</li>\n  <li>Once approved, refunds are credited back to the original source of payment (bank account, UPI, or card) within <strong>7 to 10 working days</strong>.</li>\n</ul>\n<h2>7. Grievance &amp; Escalation</h2>\n<p>If you have an unresolved billing or refund query, you may reach out directly to management:</p>\n<p>EUROPA FUSION PRIVATE LIMITED</p>\n<p>Office No. 715A, Spencer Plaza, Anna Salai, Chennai, Tamil Nadu – 600002</p>\n<p>contact@europafusion.io</p>\n<p>+91 99747 98803</p>','2026-01-01',103,1,'2026-11-22 12:47:54','2026-11-22 12:47:54');
