LOCK TABLES `services` WRITE;
/*!40000 ALTER TABLE `services` DISABLE KEYS */;
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'counselling','academic','Counselling','Clarity before commitment.','Personalized profile & path evaluation','[\"A university is chosen once and lived in for years. We begin with unhurried conversation about a student\'s strengths, interests, circumstances and means, because the soundest decisions are made with a clear view of all four.\", \"We do not steer students towards fashionable destinations or familiar names. We help them reason towards a path that is honest, achievable and worthy of their effort.\"]','The right question, asked early, saves years.','compass',1,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (2,'course-selection','academic','Course Selection','The right discipline, rightly chosen.','Targeting top accredited programs','[\"A degree shapes how a person thinks long after the lectures end. We help students look beyond titles and rankings to the substance of a programme: its curriculum, its teaching, its standing in the field and it’s fit with their intellectual strengths.\", \"Each recommendation is reasoned, comparative and candid, so that the course a student enters is one they can commit to fully.\"]','Choose the subject. Then choose the institution.','journal-bookmark',2,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (3,'applications','academic','Applications','Precision in every submission.','SOP, CV & university documentation','[\"An application is a student\'s first piece of scholarship. It should be accurate, coherent, and entirely their own.\", \"We review each component with care, from academic records and personal statements to references and supporting documents, and refine them with the student, never for them. The result is a submission that speaks plainly, withstands scrutiny, and reflects genuine purpose.\"]','Your voice, presented at its best.','file-earmark-text',3,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (4,'visa-guidance','academic','Visa Guidance','Order and assurance.','Embassy checklist & file preparation','[\"Immigration requirements are exacting, and small oversights carry real consequences. We bring structure to the process: the documents required, the evidence to be assembled and the timelines to be observed.\", \"Students are prepared for each stage with clarity, so they approach the visa process informed and composed rather than uncertain.\"]','Every requirement understood. Every document in order.','passport',4,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (5,'test-preparation','academic','Test Preparation','Readiness through discipline.','Language & entrance exam coaching','[\"Examination results are often the threshold to admission. We prepare students for them through structured instruction, regular practice and honest assessment of progress.\", \"The aim is not to teach shortcuts but to build real command of language and reasoning, so that performance on the day reflects true ability.\"]','Preparation is the quietest form of confidence.','pencil-square',5,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (6,'scholarships','academic','Scholarships','Merit, recognised.','Merit recognition & financial grants','[\"Many awards go unclaimed because they are never discovered, or are poorly presented. We help students identify the scholarships, bursaries and grants for which they may rightfully compete.\", \"We then assist in presenting their achievements, character and promise with clarity and economy, in the manner such committees value.\"]','Excellence deserves to be seen.','award',6,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (7,'education-finance','beyond','Education Finance','Ambition, responsibly funded.','Blocked accounts & loan advisory','[\"Studying abroad is a significant financial undertaking. We guide families through the available means of financing it, explaining the commitments involved and the documentation required.\", \"Our concern is prudence: that a student begins their studies with a plan they understand and obligations they can manage.\"]','Plan the cost before the journey.','bank',7,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (8,'travel-arrangements','beyond','Travel Arrangements','A considered departure.','Flights, routing & transit guidance','[\"The journey to a new country should not distract from the purpose of making it. We help students arrange their travel with attention to timing, routes, and the practicalities of arrival.\", \"It is a small service with a simple aim: that attention remains on what lies ahead.\"]','Depart with nothing left to chance.','airplane',8,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (9,'accommodation','beyond','Accommodation','A place to think and to rest.','Dormitory & student housing search','[\"Where a student lives shapes how well they study. We help secure lodging that is safe, suitable and well situated, whether within the university or beyond it, and arranged before arrival wherever possible.\", \"A settled home makes for a steadier mind.\"]','A settled home makes for a steadier mind.','house-door',9,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (10,'pre-departure-briefing','beyond','Pre-Departure Briefing','Prepared in mind and manner.','Cultural orientation & packing prep','[\"Every country has its customs, expectations and unwritten rules. Before departure, we brief students on academic conduct, daily life, cultural norms and practical matters, so that the first weeks abroad are met with understanding rather than surprise.\"]','To arrive informed is to arrive at ease.','luggage',10,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `services` (`id`, `slug`, `group`, `title`, `tagline`, `summary`, `body`, `quote`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (11,'arrival-and-settlement','beyond','Arrival and Settlement','Welcomed on arrival.','City registration & bank setup support','[\"The first days in a new country matter. We support students on landing and through the early period of settling in, so that unfamiliar surroundings become familiar quickly and studies can begin well.\"]','The journey ends. The scholarship begins.','geo-alt',11,'2026-11-22 12:47:54','2026-11-22 12:47:54');
/*!40000 ALTER TABLE `services` ENABLE KEYS */;
UNLOCK TABLES;

