INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'language','IELTS','IELTS','International English Language Testing System','Available in Academic and General Training forms, with the Speaking assessment conducted as a face-to-face interview. Widely accepted globally.','[]','headphones',1,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (2,'language','TOEFL iBT','TOEFL iBT','Test of English as a Foreign Language','A computer-based examination testing academic English. Heavily favoured by North American institutions.','[]','display',2,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (3,'language','PTE Academic','PTE Academic','Pearson Test of English','A fully computer-marked assessment known for the rapid return of results and objective scoring of spoken English.','[]','file-earmark-text',3,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (4,'language','Duolingo English Test','Duolingo English Test','','An adaptive, home-administered test increasingly accepted as a flexible alternative to traditional centre-based examinations.','[]','globe2',4,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (5,'language','CAEL','CAEL','Canadian Academic English Language','Designed specifically for entry to Canadian institutions, evaluating language use in academic contexts.','[]','vector-pen',5,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (6,'language','CELPIP','CELPIP','Canadian English Language Proficiency Index Program','For immigration and professional certification in Canada, assessing functional English for everyday situations.','[]','patch-check',6,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (7,'standardized','GRE','GRE','Graduate Record Examinations','Required for many graduate programmes, assessing verbal reasoning, quantitative reasoning, and analytical writing.','[\"Verbal\", \"Quantitative\", \"Writing\"]','calculator',7,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (8,'standardized','GMAT','GMAT','Graduate Management Admission Test','The standard assessment for MBA and other postgraduate business programmes, evaluating analytical and problem-solving abilities.','[\"MBA\", \"Analytical\", \"Problem-Solving\"]','briefcase',8,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (9,'standardized','dMAT','dMAT','Digital Master Assessment Test','Specialised assessment preparation tailored for German university entrance requirements for Master\'s programmes.','[\"Germany\", \"Master\'s\", \"Digital\"]','mortarboard',9,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (10,'standardized','SAT','SAT','Scholastic Assessment Test','A multiple-choice test used widely for undergraduate admissions in the United States and other countries.','[\"Undergraduate\", \"US Admissions\"]','pencil',10,'2026-11-22 12:47:54','2026-11-22 12:47:54');
INSERT INTO `exams` (`id`, `category`, `code`, `name`, `full_name`, `description`, `tags`, `icon`, `sort_order`, `created_at`, `updated_at`) VALUES (11,'standardized','ACT','ACT','American College Testing','An alternative to the SAT, covering English, mathematics, reading, and science, with an optional writing section.','[\"Science\", \"English\", \"Math\"]','journal-check',11,'2026-11-22 12:47:54','2026-11-22 12:47:54');
