INSERT INTO `faqs` (`id`, `group`, `question`, `answer`, `sort_order`, `created_at`, `updated_at`) VALUES (6,'exam-prep','How long does preparation usually take?','Preparation timelines vary by student and examination, but typically range from 4 to 12 weeks of focused study. After an initial diagnostic, we create a personalised timeline that works backwards from your application deadlines.',1,'2026-11-22 13:11:34','2026-11-22 13:11:34');
INSERT INTO `faqs` (`id`, `group`, `question`, `answer`, `sort_order`, `created_at`, `updated_at`) VALUES (7,'exam-prep','Do I need to take both the IELTS and TOEFL?','No. Most institutions will accept either. We advise taking a diagnostic test to determine which format better suits your strengths. We then help you focus entirely on one examination to maximise your score.',2,'2026-11-22 13:11:34','2026-11-22 13:11:34');
INSERT INTO `faqs` (`id`, `group`, `question`, `answer`, `sort_order`, `created_at`, `updated_at`) VALUES (8,'exam-prep','When should I start preparing?','We recommend beginning preparation at least 3 to 6 months before your application deadlines to allow time for thorough preparation and a retake if necessary.',3,'2026-11-22 13:11:34','2026-11-22 13:11:34');
INSERT INTO `faqs` (`id`, `group`, `question`, `answer`, `sort_order`, `created_at`, `updated_at`) VALUES (9,'exam-prep','Are materials provided?','Yes, all necessary study materials, including proprietary practice tests, diagnostic tools, and comprehensive e-books are included in our preparation programmes.',4,'2026-11-22 13:11:34','2026-11-22 13:11:34');
INSERT INTO `faqs` (`id`, `group`, `question`, `answer`, `sort_order`, `created_at`, `updated_at`) VALUES (10,'exam-prep','What is your approach to test preparation?','Each student begins with an assessment under examination conditions. The result — not a fixed syllabus — determines the course of study. We focus on the specific areas where you need improvement.',5,'2026-11-22 13:11:34','2026-11-22 13:11:34');
